// Additional questions - loaded after data.js, pushed into the existing QUESTIONS array
QUESTIONS.push(
  // ===== LECTURA CRITICA - BLOQUE 5 (LC61-LC100) =====
  {id:'LC61',area:'lectura',areaName:'Lectura Critica',difficulty:'facil',context:`"La lectura critica implica analizar no solo lo que dice un texto, sino tambien como lo dice, quien lo dice y con que proposito."`,question:`La lectura critica va mas alla de entender el contenido porque tambien analiza:`,options:['Solo el vocabulario usado','El contexto, proposito y autor del texto','La longitud del texto','La cantidad de parrafos'],correct:1,explanation:{correct:'La lectura critica analiza "como lo dice, quien lo dice y con que proposito", no solo el contenido superficial.',wrongs:['El vocabulario es solo un aspecto','Opcion correcta','La longitud no es relevante','Los parrafos no determinan el analisis critico']}},
  {id:'LC62',area:'lectura',areaName:'Lectura Critica',difficulty:'media',context:`"La economia colombiana tuvo un crecimiento del 2.5% durante el ultimo trimestre, impulsada por el sector de servicios y la construccion. Sin embargo, la inflacion se mantiene en niveles elevados, afectando el poder adquisitivo de los hogares."`,question:`Segun el texto, que sector impulso el crecimiento economico?`,options:['La agricultura y la mineria','Los servicios y la construccion','La tecnologia y la manufactura','El turismo y la gastronomia'],correct:1,explanation:{correct:'El texto menciona que el crecimiento fue "impulsada por el sector de servicios y la construccion".',wrongs:['No se mencionan agricultura o mineria','Opcion correcta','Tecnologia y manufactura no se mencionan','Turismo y gastronomia no se mencionan']}},
  {id:'LC63',area:'lectura',areaName:'Lectura Critica',difficulty:'dificil',context:`"La 'disonancia cognitiva' es un concepto psicologico que describe el malestar que experimentamos cuando sostenemos dos creencias contradictorias o cuando nuestras acciones contradicen nuestras creencias."`,question:`La disonancia cognitiva genera:`,options:['Tranquilidad y certeza','Malestar por contradiccion entre creencias o entre creencias y acciones','Indiferencia ante la informacion','Fortalecimiento de las convicciones'],correct:1,explanation:{correct:'La disonancia cognitiva es "el malestar que experimentamos cuando sostenemos dos creencias contradictorias" o cuando acciones y creencias chocan.',wrongs:['La disonancia genera malestar, no tranquilidad','Opcion correcta','La disonancia es incomoda, no indiferente','La disonancia debilita, no fortalece']}},
  {id:'LC64',area:'lectura',areaName:'Lectura Critica',difficulty:'facil',context:`"Colombia cuenta con 59 parques naturales nacionales que protegen la biodiversidad del pais. Estas areas protegidas cubren aproximadamente el 11% del territorio nacional."`,question:`Que porcentaje del territorio colombiano esta cubierto por parques naturales?`,options:['5%','11%','20%','30%'],correct:1,explanation:{correct:'El texto dice que los parques naturales "cubren aproximadamente el 11% del territorio nacional".',wrongs:['Menos de lo indicado','Opcion correcta','Mas de lo indicado','Mas de lo indicado']}},
  {id:'LC65',area:'lectura',areaName:'Lectura Critica',difficulty:'media',context:`"El teletrabajo en Colombia fue regulado por la Ley 1221 de 2008, que lo define como una forma de organizacion laboral que utiliza tecnologias de la informacion para realizar trabajo fuera del sitio de trabajo tradicional."`,question:`La Ley 1221 de 2008 en Colombia regula:`,options:['El salario minimo','El teletrabajo','La jornada laboral nocturna','Las prestaciones sociales'],correct:1,explanation:{correct:'La Ley 1221 de 2008 regula el teletrabajo, definiendolo como trabajo que utiliza TIC fuera del sitio tradicional.',wrongs:['El salario minimo tiene otra regulacion','Opcion correcta','La jornada nocturna esta en otro codigo','Las prestaciones estan en el CST']}},
  {id:'LC66',area:'lectura',areaName:'Lectura Critica',difficulty:'dificil',context:`"El 'circulo hermeneutico' describe el proceso interpretativo en el que la comprension de un texto se construye a partir de la relacion entre sus partes y el todo. No se puede entender una parte sin entender el todo, y viceversa."`,question:`El circulo hermeneutico afirma que la comprension de un texto:`,options:['Es lineal y secuencial','Depende de la relacion entre las partes y el todo','Se logra solo con el diccionario','Es automatica e inmediata'],correct:1,explanation:{correct:'El circulo hermeneutico dice que "no se puede entender una parte sin entender el todo, y viceversa", hay una relacion dialectica.',wrongs:['La interpretacion no es lineal sino circular','Opcion correcta','Va mas alla del significado literal','Requiere un proceso consciente']}},
  {id:'LC67',area:'lectura',areaName:'Lectura Critica',difficulty:'media',context:`"La economia colaborativa, ejemplificada por plataformas como Uber y Airbnb, ha transformado sectores tradicionales al permitir que las personas compartan bienes y servicios directamente."`,question:`La economia colaborativa se caracteriza por:`,options:['La centralizacion en grandes empresas','El intercambio directo de bienes y servicios entre personas','La eliminacion de la tecnologia','El aumento de regulaciones estatales'],correct:1,explanation:{correct:'La economia colaborativa "permite que las personas compartan bienes y servicios directamente", usando plataformas digitales.',wrongs:['Es descentralizada, no centralizada','Opcion correcta','Se basa en tecnologia digital','Busca reducir regulaciones']}},
  {id:'LC68',area:'lectura',areaName:'Lectura Critica',difficulty:'facil',context:`"El consumo responsable implica elegir productos que tengan el menor impacto ambiental posible, considerando todo su ciclo de vida: desde la produccion hasta la disposicion final."`,question:`El consumo responsable considera:`,options:['Solo el precio del producto','El impacto ambiental durante todo el ciclo de vida','Unicamente la marca del producto','La cantidad de empaque'],correct:1,explanation:{correct:'El consumo responsable considera "todo el ciclo de vida: desde la produccion hasta la disposicion final".',wrongs:['No solo el precio, tambien el impacto','Opcion correcta','La marca no es el criterio principal','El empaque es solo un aspecto']}},
  {id:'LC69',area:'lectura',areaName:'Lectura Critica',difficulty:'dificil',context:`"El 'velo de la ignorancia' de John Rawls es un experimento mental en el que las personas disenan una sociedad justa sin saber que posicion ocuparan en ella. Esto garantiza que las reglas sean imparciales."`,question:`El velo de la ignorancia busca garantizar:`,options:['El beneficio de los mas poderosos','La imparcialidad al disenar reglas sociales','El conocimiento total de cada persona','La eliminacion de las diferencias'],correct:1,explanation:{correct:'Rawls propone que "sin saber que posicion ocuparan" las personas disenaran reglas imparciales y justas para todos.',wrongs:['Busca justicia, no beneficio del poderoso','Opcion correcta','Precisamente propone ignorar la posicion social','No elimina diferencias, sino que las regula justamente']}},
  {id:'LC70',area:'lectura',areaName:'Lectura Critica',difficulty:'media',context:`"Los videojuegos han pasado de ser considerados un pasatiempo a ser reconocidos como una industria cultural que genera mas ingresos que el cine y la musica combinados."`,question:`Segun el texto, los videojuegos actualmente son:`,options:['Un simple pasatiempo infantil','Una industria cultural de gran impacto economico','Una actividad sin relevancia cultural','Un sector en declive'],correct:1,explanation:{correct:'Los videojuegos son "una industria cultural que genera mas ingresos que el cine y la musica combinados".',wrongs:['Ya no son solo un pasatiempo','Opcion correcta','Tienen gran relevancia cultural y economica','Es un sector en crecimiento']}},
  {id:'LC71',area:'lectura',areaName:'Lectura Critica',difficulty:'facil',context:`"La energia hidroelectrica representa aproximadamente el 70% de la generacion electrica en Colombia, gracias a la abundancia de recursos hidricos en el pais."`,question:`Que porcentaje de la electricidad colombiana proviene de hidroelectricas?`,options:['50%','70%','90%','30%'],correct:1,explanation:{correct:'La energia hidroelectrica "representa aproximadamente el 70% de la generacion electrica en Colombia".',wrongs:['Es mas del 50%','Opcion correcta','Es menos del 90%','Es mas del 30%']}},
  {id:'LC72',area:'lectura',areaName:'Lectura Critica',difficulty:'dificil',context:`"La 'racionalidad limitada' de Herbert Simon plantea que las personas toman decisiones no con informacion perfecta, sino con limitaciones de tiempo, informacion y capacidad cognitiva. Por eso, nos conformamos con soluciones 'suficientemente buenas'."`,question:`La racionalidad limitada explica que las personas:`,options:['Toman decisiones optimas siempre','Se conforman con soluciones suficientemente buenas dadas sus limitaciones','No toman decisiones racionales nunca','Solo usan la intuicion'],correct:1,explanation:{correct:'Simon dice que por limitaciones cognitivas y de informacion, las personas se conforman con "soluciones suficientemente buenas" (satisficing).',wrongs:['No siempre tomamos decisiones optimas','Opcion correcta','Si hay racionalidad, pero limitada','No solo intuicion, tambien razon limitada']}},
  {id:'LC73',area:'lectura',areaName:'Lectura Critica',difficulty:'media',context:`"La biodiversidad colombiana incluye aproximadamente 1.900 especies de aves, lo que representa el 20% de todas las especies del planeta. Colombia es el pais con mayor diversidad de aves del mundo."`,question:`Colombia se destaca mundialmente por:`,options:['Tener la mayor diversidad de aves del mundo','Tener la mayor extension territorial','Ser el pais mas poblado','Tener el mayor PIB'],correct:0,explanation:{correct:'Colombia es "el pais con mayor diversidad de aves del mundo", con el 20% de todas las especies.',wrongs:['Opcion correcta','No es el mas extenso','No es el mas poblado','No tiene el mayor PIB']}},
  {id:'LC74',area:'lectura',areaName:'Lectura Critica',difficulty:'facil',context:`"La OMS define la salud como un estado completo de bienestar fisico, mental y social, y no solamente la ausencia de enfermedades."`,question:`Segun la OMS, la salud incluye:`,options:['Solo el bienestar fisico','Bienestar fisico, mental y social','Ausencia total de sintomas','La capacidad de trabajar'],correct:1,explanation:{correct:'La OMS define salud como "un estado completo de bienestar fisico, mental y social", no solo ausencia de enfermedad.',wrongs:['Incluye tambien salud mental y social','Opcion correcta','Va mas alla de los sintomas','El trabajo es solo una parte']}},
  {id:'LC75',area:'lectura',areaName:'Lectura Critica',difficulty:'dificil',context:`"La 'paradoja de la tolerancia' de Karl Popper sostiene que una sociedad tolerante no puede tolerar la intolerancia, porque si lo hace, la intolerancia destruira la tolerancia misma."`,question:`La paradoja de la tolerancia implica que:`,options:['La tolerancia debe ser ilimitada','Para preservar la tolerancia, no se debe tolerar la intolerancia','La intolerancia es inevitable','Todas las ideas merecen igual respeto'],correct:1,explanation:{correct:'Popper dice que si toleramos la intolerancia, esta destruira la tolerancia. Por tanto, para defender la tolerancia debemos limitar la intolerancia.',wrongs:['La tolerancia tiene limites: la intolerancia','Opcion correcta','La intolerancia puede combatirse','No todas, la intolerancia debe ser contenida']}},
  {id:'LC76',area:'lectura',areaName:'Lectura Critica',difficulty:'media',context:`"Los derechos de autor protegen las creaciones intelectuales como obras literarias, musicales, artisticas y software. En Colombia, la proteccion dura toda la vida del autor mas 80 anos despues de su muerte."`,question:`Cuantos duran los derechos de autor en Colombia despues de la muerte del autor?`,options:['50 anos','70 anos','80 anos','100 anos'],correct:2,explanation:{correct:'En Colombia, los derechos de autor duran "toda la vida del autor mas 80 anos despues de su muerte".',wrongs:['50 anos es el estandar en otros paises','70 anos aplica en la UE','Opcion correcta','No son 100 anos']}},
  {id:'LC77',area:'lectura',areaName:'Lectura Critica',difficulty:'facil',context:`"Las redes sociales pueden tener efectos positivos en la salud mental al proporcionar apoyo social, pero tambien efectos negativos como ansiedad y comparacion social."`,question:`Las redes sociales tienen efectos en la salud mental que son:`,options:['Solo positivos','Solo negativos','Tanto positivos como negativos','Inexistentes'],correct:2,explanation:{correct:'Las redes sociales tienen "efectos positivos" (apoyo social) y "efectos negativos" (ansiedad, comparacion social).',wrongs:['Tambien hay efectos negativos','Tambien hay efectos positivos','Opcion correcta','Si tienen efectos']}},
  {id:'LC78',area:'lectura',areaName:'Lectura Critica',difficulty:'dificil',context:`"El 'sesgo de confirmacion' es la tendencia a buscar, interpretar y recordar informacion que confirma nuestras creencias previas, ignorando la evidencia que las contradice."`,question:`El sesgo de confirmacion nos lleva a:`,options:['Evaluar la evidencia de forma objetiva','Buscar informacion que confirme lo que ya creemos','Cambiar de opinion facilmente','Aceptar todas las criticas'],correct:1,explanation:{correct:'El sesgo de confirmacion es "la tendencia a buscar, interpretar y recordar informacion que confirma nuestras creencias previas".',wrongs:['El sesgo impide la objetividad','Opcion correcta','Dificulta el cambio de opinion','Ignora las criticas']}},
  {id:'LC79',area:'lectura',areaName:'Lectura Critica',difficulty:'media',context:`"La masificacion de la inteligencia artificial generativa plantea preguntas sobre la autoria, la originalidad y el futuro del trabajo creativo. Puede una maquina ser realmente creativa?"`,question:`La IA generativa plantea interrogantes sobre:`,options:['La velocidad de los computadores','La autoria, originalidad y creatividad','El precio de la tecnologia','Los lenguajes de programacion'],correct:1,explanation:{correct:'La IA generativa plantea "preguntas sobre la autoria, la originalidad y el futuro del trabajo creativo".',wrongs:['No se cuestiona la velocidad','Opcion correcta','El precio no es el tema central','No es sobre lenguajes']}},
  {id:'LC80',area:'lectura',areaName:'Lectura Critica',difficulty:'facil',context:`"El servicio militar obligatorio en Colombia esta regulado por la Ley 48 de 1993. Todos los varones colombianos mayores de 18 anos tienen la obligacion de definir su situacion militar."`,question:`Segun la Ley 48 de 1993, el servicio militar en Colombia es:`,options:['Voluntario para todos','Obligatorio para varones mayores de 18 anos','Solo para mujeres','Inexistente'],correct:1,explanation:{correct:'La ley establece que "todos los varones colombianos mayores de 18 anos tienen la obligacion de definir su situacion militar".',wrongs:['Es obligatorio, no voluntario','Opcion correcta','Aplica principalmente a varones','Si existe y esta regulado']}},
  {id:'LC81',area:'lectura',areaName:'Lectura Critica',difficulty:'dificil',context:`"El 'experimento mental del barco de Teseo' pregunta si un barco al que se le reemplazan todas sus partes sigue siendo el mismo barco. Esta paradoja explora la identidad a traves del cambio."`,question:`El barco de Teseo es una paradoja sobre:`,options:['La navegacion maritima','La identidad y el cambio a traves del tiempo','La construccion naval','El origen de los barcos'],correct:1,explanation:{correct:'La paradoja "explora la identidad a traves del cambio": si reemplazamos todas las partes, sigue siendo el mismo barco?',wrongs:['No es sobre navegacion','Opcion correcta','No es sobre construccion','No es sobre origenes']}},
  {id:'LC82',area:'lectura',areaName:'Lectura Critica',difficulty:'media',context:`"La desercion universitaria en Colombia alcanza el 47%, segun el Ministerio de Educacion. Las principales causas son dificultades economicas, falta de orientacion vocacional y problemas academicos."`,question:`Cual es la tasa de desercion universitaria en Colombia?`,options:['25%','35%','47%','60%'],correct:2,explanation:{correct:'La desercion universitaria "alcanza el 47%, segun el Ministerio de Educacion".',wrongs:['Menos de lo reportado','Menos de lo reportado','Opcion correcta','Mas de lo reportado']}},
  {id:'LC83',area:'lectura',areaName:'Lectura Critica',difficulty:'facil',context:`"El reciclaje de papel ayuda a reducir la tala de arboles. Por cada tonelada de papel reciclado, se salvan aproximadamente 17 arboles."`,question:`Cuantos arboles se salvan por cada tonelada de papel reciclado?`,options:['7','12','17','25'],correct:2,explanation:{correct:'"Por cada tonelada de papel reciclado, se salvan aproximadamente 17 arboles."',wrongs:['Menos de lo indicado','Menos de lo indicado','Opcion correcta','Mas de lo indicado']}},
  {id:'LC84',area:'lectura',areaName:'Lectura Critica',difficulty:'dificil',context:`"El 'efecto placebo' es un fenomeno en el que una persona experimenta una mejoria real en sus sintomas despues de recibir un tratamiento sin principio activo, debido a sus expectativas y creencias sobre el tratamiento."`,question:`El efecto placebo demuestra que:`,options:['Los medicamentos no funcionan','Las expectativas y creencias pueden influir en la salud real','Todos los tratamientos son iguales','La mente no afecta al cuerpo'],correct:1,explanation:{correct:'El placebo muestra que "las expectativas y creencias sobre el tratamiento" pueden producir "una mejoria real" incluso sin principio activo.',wrongs:['Los medicamentos si funcionan, pero la mente tambien influye','Opcion correcta','Los placebos no curan todo','Si hay conexion mente-cuerpo']}},
  {id:'LC85',area:'lectura',areaName:'Lectura Critica',difficulty:'media',context:`"La politica de 'cero papel' en la administracion publica colombiana busca digitalizar los procesos y reducir el uso de papel, mejorando la eficiencia y disminuyendo el impacto ambiental."`,question:`La politica de cero papel busca:`,options:['Aumentar el uso de papel reciclado','Digitalizar procesos para reducir el uso de papel','Eliminar todos los documentos','Prohibir las impresoras'],correct:1,explanation:{correct:'Busca "digitalizar los procesos y reducir el uso de papel, mejorando la eficiencia" y reduciendo impacto ambiental.',wrongs:['Busca reducir, no solo reciclar','Opcion correcta','No elimina todo, digitaliza','No prohibe, reduce']}},
  {id:'LC86',area:'lectura',areaName:'Lectura Critica',difficulty:'facil',context:`"Un estudio revelo que el 65% de los estudiantes colombianos usa internet principalmente para redes sociales, mientras que solo el 20% lo usa para fines educativos."`,question:`Para que usa internet la mayoria de los estudiantes colombianos?`,options:['Fines educativos','Redes sociales','Trabajo','Compras en linea'],correct:1,explanation:{correct:'El 65% usa internet "principalmente para redes sociales", mientras que solo el 20% para fines educativos.',wrongs:['Solo el 20% lo usa educativamente','Opcion correcta','No se menciona trabajo','No se mencionan compras']}},
  {id:'LC87',area:'lectura',areaName:'Lectura Critica',difficulty:'dificil',context:`"La 'tragedia de los comunes' describe una situacion en la que individuos que comparten un recurso comun actuan en su propio interes, agotando el recurso a largo plazo en detrimento de todos."`,question:`La tragedia de los comunes ocurre cuando:`,options:['El Estado gestiona eficientemente los recursos','Individuos buscan su interes personal y agotan un recurso compartido','Las comunidades cooperan voluntariamente','Los recursos son privados'],correct:1,explanation:{correct:'Ocurre cuando individuos "actuan en su propio interes, agotando el recurso a largo plazo en detrimento de todos".',wrongs:['El Estado puede prevenirla con regulacion','Opcion correcta','La cooperacion evitaria la tragedia','La privatizacion es una solucion propuesta']}},
  {id:'LC88',area:'lectura',areaName:'Lectura Critica',difficulty:'media',context:`"La reforma pensional en Colombia busca garantizar la sostenibilidad del sistema de pensiones y ampliar la cobertura a mas personas, especialmente a los trabajadores informales."`,question:`La reforma pensional busca principalmente:`,options:['Reducir todas las pensiones','Garantizar sostenibilidad y ampliar cobertura','Eliminar el sistema de pensiones','Privatizar completamente las pensiones'],correct:1,explanation:{correct:'Busca "garantizar la sostenibilidad del sistema de pensiones y ampliar la cobertura a mas personas".',wrongs:['No busca reducirlas, sino sostenerlas','Opcion correcta','Busca fortalecer el sistema','No propone privatizacion total']}},
  {id:'LC89',area:'lectura',areaName:'Lectura Critica',difficulty:'facil',context:`"El aguacate se ha convertido en uno de los productos de exportacion mas importantes de Colombia, con envios que superan los 100 millones de dolares anuales."`,question:`El aguacate es importante para Colombia porque:`,options:['Es el unico producto de exportacion','Genera mas de 100 millones de dolares anuales en exportaciones','Se consume solo localmente','No tiene demanda internacional'],correct:1,explanation:{correct:'Las exportaciones de aguacate "superan los 100 millones de dolares anuales", siendo un producto clave.',wrongs:['Hay muchos productos de exportacion','Opcion correcta','Se exporta principalmente','Tiene alta demanda internacional']}},
  {id:'LC90',area:'lectura',areaName:'Lectura Critica',difficulty:'dificil',context:`"La 'navaja de Occam' es un principio metodologico que, ante dos explicaciones competidoras, favorece la mas simple, es decir, la que requiere menos suposiciones."`,question:`La navaja de Occam recomienda:`,options:['Preferir explicaciones complejas','Elegir la explicacion mas simple con menos suposiciones','Ignorar la evidencia disponible','Aceptar todas las explicaciones por igual'],correct:1,explanation:{correct:'La navaja de Occam "favorece la mas simple, es decir, la que requiere menos suposiciones".',wrongs:['Prefiere la simplicidad','Opcion correcta','Se basa en la evidencia','Jerarquiza las explicaciones']}},
  {id:'LC91',area:'lectura',areaName:'Lectura Critica',difficulty:'media',context:`"La movilidad sostenible incluye el uso de transporte publico, bicicletas y vehiculos electricos, buscando reducir las emisiones de gases de efecto invernadero y mejorar la calidad del aire."`,question:`Que busca la movilidad sostenible?`,options:['Aumentar el uso de automoviles particulares','Reducir emisiones y mejorar la calidad del aire','Construir mas autopistas','Eliminar el transporte publico'],correct:1,explanation:{correct:'Busca "reducir las emisiones de gases de efecto invernadero y mejorar la calidad del aire".',wrongs:['Busca reducir el uso de autos','Opcion correcta','No solo autopistas','Promueve el transporte publico']}},
  {id:'LC92',area:'lectura',areaName:'Lectura Critica',difficulty:'facil',context:`"El 'cyborg' es un organismo que combina componentes biologicos y tecnologicos. Hoy en dia, los marcapasos y los implantes cocleares son ejemplos de tecnologia cyborg."`,question:`Un cyborg es un organismo que:`,options:['Es completamente artificial','Combina componentes biologicos y tecnologicos','Solo existe en la ciencia ficcion','Es puramente biologico'],correct:1,explanation:{correct:'El cyborg "combina componentes biologicos y tecnologicos", como marcapasos o implantes cocleares.',wrongs:['Tiene componentes biologicos tambien','Opcion correcta','Ya existen ejemplos reales','Combina biologia con tecnologia']}},
  {id:'LC93',area:'lectura',areaName:'Lectura Critica',difficulty:'dificil',context:`"El 'darwinismo social' es una teoria pseudocientifica que aplica incorrectamente los conceptos de seleccion natural y 'supervivencia del mas apto' a las sociedades humanas, justificando desigualdades."`,question:`El darwinismo social es considerado una teoria:`,options:['Cientificamente valida','Pseudocientifica que justifica desigualdades','Basada en evidencia genetica','Aprobada por Darwin'],correct:1,explanation:{correct:'Es una "teoria pseudocientifica" que aplica incorrectamente conceptos de Darwin para "justificar desigualdades".',wrongs:['No tiene validez cientifica','Opcion correcta','No tiene base genetica real','Darwin no la aprobo']}},
  {id:'LC94',area:'lectura',areaName:'Lectura Critica',difficulty:'media',context:`"Colombia es el segundo productor mundial de cafe despues de Brasil. El cafe colombiano es reconocido internacionalmente por su calidad y sabor suave."`,question:`Colombia es el _____ productor mundial de cafe:`,options:['Primer','Segundo','Tercer','Quinto'],correct:1,explanation:{correct:'Colombia es "el segundo productor mundial de cafe despues de Brasil".',wrongs:['Brasil es el primero','Opcion correcta','Es segundo, no tercero','Es segundo, no quinto']}},
  {id:'LC95',area:'lectura',areaName:'Lectura Critica',difficulty:'facil',context:`"La donacion de organos es un acto voluntario que puede salvar vidas. En Colombia, la Ley 1805 de 2016 establecio que todos somos donantes potenciales, a menos que manifestemos lo contrario."`,question:`Segun la Ley 1805 de 2016, en Colombia:`,options:['La donacion de organos esta prohibida','Todos son donantes potenciales a menos que manifiesten lo contrario','Solo los familiares pueden donar','La donacion requiere pago'],correct:1,explanation:{correct:'La ley establece que "todos somos donantes potenciales, a menos que manifestemos lo contrario" (consentimiento presunto).',wrongs:['La donacion esta permitida y promovida','Opcion correcta','Cualquier persona puede ser donante','La donacion es voluntaria y gratuita']}},
  {id:'LC96',area:'lectura',areaName:'Lectura Critica',difficulty:'dificil',context:`"El 'problema del marco' en filosofia de la inteligencia artificial se refiere a la dificultad de programar un agente para que distinga entre la informacion relevante e irrelevante en un contexto dado."`,question:`El problema del marco en IA se refiere a:`,options:['El costo de los computadores','La dificultad de distinguir informacion relevante de irrelevante','La falta de memoria en los sistemas','El consumo energetico'],correct:1,explanation:{correct:'Es "la dificultad de programar un agente para que distinga entre la informacion relevante e irrelevante en un contexto".',wrongs:['No es sobre costos','Opcion correcta','No es sobre memoria','No es sobre energia']}},
  {id:'LC97',area:'lectura',areaName:'Lectura Critica',difficulty:'media',context:`"El acoso escolar o 'bullying' afecta a aproximadamente 1 de cada 3 estudiantes en Colombia, segun la Encuesta de Convivencia Escolar del Ministerio de Educacion."`,question:`En Colombia, el bullying afecta aproximadamente a:`,options:['1 de cada 10 estudiantes','1 de cada 3 estudiantes','1 de cada 2 estudiantes','Todos los estudiantes'],correct:1,explanation:{correct:'El bullying "afecta a aproximadamente 1 de cada 3 estudiantes en Colombia".',wrongs:['Afecta a mas del 10%','Opcion correcta','No llega al 50%','No afecta a todos']}},
  {id:'LC98',area:'lectura',areaName:'Lectura Critica',difficulty:'facil',context:`"La huella hidrica mide el volumen total de agua dulce utilizado para producir bienes y servicios. Producir una taza de cafe requiere aproximadamente 140 litros de agua."`,question:`La huella hidrica mide:`,options:['La contaminacion del agua','El volumen de agua dulce usado para producir bienes y servicios','La cantidad de agua en los oceanos','El nivel de los rios'],correct:1,explanation:{correct:'La huella hidrica mide "el volumen total de agua dulce utilizado para producir bienes y servicios".',wrongs:['Mide consumo, no contaminacion','Opcion correcta','No mide oceanos','No mide niveles fluviales']}},
  {id:'LC99',area:'lectura',areaName:'Lectura Critica',difficulty:'dificil',context:`"El 'solipsismo' es una posicion filosofica radical que sostiene que solo la propia mente existe con certeza. El mundo exterior y otras mentes podrian ser meras ilusiones."`,question:`El solipsismo afirma que:`,options:['El mundo exterior existe objetivamente','Solo la propia mente existe con certeza','Todas las mentes son iguales','La realidad es socialmente construida'],correct:1,explanation:{correct:'El solipsismo sostiene que "solo la propia mente existe con certeza" y que el mundo exterior podria ser ilusion.',wrongs:['Niega la certeza del mundo exterior','Opcion correcta','Solo reconoce la propia mente','Va mas alla del constructivismo']}},
  {id:'LC100',area:'lectura',areaName:'Lectura Critica',difficulty:'media',context:`"El 'efecto mariposa' de la teoria del caos sugiere que pequenas variaciones en las condiciones iniciales pueden producir grandes diferencias en el resultado a largo plazo."`,question:`El efecto mariposa describe:`,options:['Que los efectos son proporcionales a las causas','Que pequenas causas pueden tener grandes efectos a largo plazo','Que las mariposas causan huracanes','Que todo es predecible'],correct:1,explanation:{correct:'El efecto mariposa dice que "pequenas variaciones en las condiciones iniciales pueden producir grandes diferencias en el resultado".',wrongs:['No hay proporcionalidad causal','Opcion correcta','Es una metafora, no literal','El caos es impredecible a largo plazo']}},

  // ===== MATEMATICAS - BLOQUE 5 (MT61-MT100) =====
  {id:'MT61',area:'matematicas',areaName:'Matematicas',difficulty:'facil',question:`Cual es el resultado de 100 - 10 x 5?`,options:['450','50','90','450'],correct:1,explanation:{correct:'Jerarquia: primero 10x5=50, luego 100-50=50.',wrongs:['Si restas primero: (100-10)x5=450, incorrecto','Opcion correcta','Calculaste 100-10=90, olvidando la multiplicacion','Repetido']}},
  {id:'MT62',area:'matematicas',areaName:'Matematicas',difficulty:'media',question:`La expresion (x + 3)(x - 3) es igual a:`,options:['x2 + 9','x2 - 9','x2 - 6x + 9','x2 + 6x - 9'],correct:1,explanation:{correct:'(x + 3)(x - 3) = x2 - 3x + 3x - 9 = x2 - 9. Es una diferencia de cuadrados: (a + b)(a - b) = a2 - b2.',wrongs:['(x+3)(x-3)=x2-9, no +9','Opcion correcta','Eso seria (x-3)2 = x2-6x+9','Eso seria (x+3)2 = x2+6x+9']}},
  {id:'MT63',area:'matematicas',areaName:'Matematicas',difficulty:'dificil',question:`Cual es la probabilidad de obtener un numero par al lanzar un dado de 6 caras?`,options:['1/6','1/3','1/2','2/3'],correct:2,explanation:{correct:'Numeros pares en un dado: 2, 4, 6 = 3 casos. Total: 6. Probabilidad = 3/6 = 1/2.',wrongs:['Esa es la probabilidad de un numero especifico','Eso serian 2 numeros pares, pero hay 3','Opcion correcta','Eso serian 4 numeros pares']}},
  {id:'MT64',area:'matematicas',areaName:'Matematicas',difficulty:'facil',question:`Si a = 2 y b = 5, cuanto es 3a + 2b?`,options:['16','10','21','11'],correct:0,explanation:{correct:'3a + 2b = 3(2) + 2(5) = 6 + 10 = 16.',wrongs:['Opcion correcta','Calculaste 2(5)=10, falta 3(2)=6','Sumaste 3+2+2+5?','Calculaste 3+2+2x5?']}},
  {id:'MT65',area:'matematicas',areaName:'Matematicas',difficulty:'media',question:`Un angulo de 45 es un angulo:`,options:['Recto','Agudo','Obtuso','Llano'],correct:1,explanation:{correct:'Un angulo agudo mide menos de 90. 45 < 90, por lo tanto es agudo.',wrongs:['Recto = 90','Opcion correcta','Obtuso = entre 90 y 180','Llano = 180']}},
  {id:'MT66',area:'matematicas',areaName:'Matematicas',difficulty:'dificil',context:`La siguiente tabla muestra los puntajes de 10 estudiantes: 70, 85, 90, 65, 80, 95, 75, 85, 60, 80`,question:`Cual es la mediana de estos puntajes?`,options:['80','82.5','85','78.5'],correct:0,explanation:{correct:'Ordenando: 60, 65, 70, 75, 80, 80, 85, 85, 90, 95. Con 10 datos (par), mediana = promedio del 5 y 6 = (80+80)/2 = 80.',wrongs:['Opcion correcta','Calculaste mal los valores centrales','Ese seria el tercer cuartil','Calculaste la media en lugar de mediana']}},
  {id:'MT67',area:'matematicas',areaName:'Matematicas',difficulty:'facil',question:`Cuanto es el 10% de 500?`,options:['5','10','50','100'],correct:2,explanation:{correct:'10% de 500 = 500 x 0.10 = 50.',wrongs:['Eso seria el 1%','Eso seria 500/50','Opcion correcta','Eso seria el 20%']}},
  {id:'MT68',area:'matematicas',areaName:'Matematicas',difficulty:'media',question:`Si 2x + 5 = 13, entonces x es:`,options:['3','4','5','9'],correct:1,explanation:{correct:'2x + 5 = 13 - 2x = 13 - 5 - 2x = 8 - x = 4.',wrongs:['Si x=3: 2(3)+5=11, no 13','Opcion correcta','Si x=5: 2(5)+5=15, no 13','Si x=9: 2(9)+5=23, no 13']}},
  {id:'MT69',area:'matematicas',areaName:'Matematicas',difficulty:'dificil',question:`La hipotenusa de un triangulo rectangulo con catetos de 6 cm y 8 cm mide:`,options:['10 cm','12 cm','14 cm','7 cm'],correct:0,explanation:{correct:'h2 = 62 + 82 = 36 + 64 = 100 - h = v100 = 10 cm.',wrongs:['Opcion correcta','Sumaste 6+8-2?','Sumaste 6+8=14, no es Pitagoras','Calculaste mal']}},
  {id:'MT70',area:'matematicas',areaName:'Matematicas',difficulty:'facil',question:`Un numero impar mas otro numero impar siempre da como resultado:`,options:['Un numero impar','Un numero par','Depende de los numeros','Cero'],correct:1,explanation:{correct:'La suma de dos numeros impares siempre es par. Ej: 3+5=8, 7+9=16.',wrongs:['Impar + impar = par','Opcion correcta','Siempre es par, no depende','No siempre es cero']}},
  {id:'MT71',area:'matematicas',areaName:'Matematicas',difficulty:'media',question:`El maximo comun divisor (MCD) de 12 y 18 es:`,options:['3','6','12','36'],correct:1,explanation:{correct:'Divisores de 12: 1,2,3,4,6,12. Divisores de 18: 1,2,3,6,9,18. Maximo comun: 6.',wrongs:['3 es divisor comun pero no el maximo','Opcion correcta','12 no es divisor de 18','36 es el MCM, no el MCD']}},
  {id:'MT72',area:'matematicas',areaName:'Matematicas',difficulty:'dificil',question:`El numero 0.0000056 en notacion cientifica es:`,options:['5.6 x 10-6','5.6 x 106','56 x 10-7','0.56 x 10-5'],correct:0,explanation:{correct:'0.0000056 = 5.6 x 10-6. Se mueve el punto decimal 6 posiciones a la derecha: exponente negativo.',wrongs:['Opcion correcta','Exponente positivo seria >1','56x10-7 no es notacion estandar (56>10)','0.56 no esta entre 1 y 10']}},
  {id:'MT73',area:'matematicas',areaName:'Matematicas',difficulty:'facil',question:`Cual de los siguientes numeros es divisible por 5?`,options:['23','34','45','52'],correct:2,explanation:{correct:'Un numero es divisible por 5 si termina en 0 o 5. 45 termina en 5.',wrongs:['23 termina en 3','34 termina en 4','Opcion correcta','52 termina en 2']}},
  {id:'MT74',area:'matematicas',areaName:'Matematicas',difficulty:'media',question:`La expresion 30 es igual a:`,options:['0','1','3','No definido'],correct:1,explanation:{correct:'Todo numero elevado a la 0 es 1 (excepto 00). 30 = 1.',wrongs:['Cualquier numero !=0 elevado a 0 es 1','Opcion correcta','31 = 3, no 30','Si esta definido: = 1']}},
  {id:'MT75',area:'matematicas',areaName:'Matematicas',difficulty:'dificil',question:`La ecuacion de la recta que pasa por el origen con pendiente -2 es:`,options:['y = 2x','y = -2x','y = x - 2','y = -2x + 1'],correct:1,explanation:{correct:'Ecuacion de la recta: y = mx + b. Pasa por origen: b = 0. Pendiente m = -2. Por tanto y = -2x.',wrongs:['La pendiente debe ser -2, no 2','Opcion correcta','El intercepto es 0, no -2','El intercepto es 0, no 1']}},
  {id:'MT76',area:'matematicas',areaName:'Matematicas',difficulty:'facil',question:`Si un cuadrado tiene perimetro 20 cm, cuanto mide cada lado?`,options:['4 cm','5 cm','10 cm','20 cm'],correct:1,explanation:{correct:'Perimetro del cuadrado = 4 x lado. 20 = 4L - L = 20/4 = 5 cm.',wrongs:['Si lado=4: perimetro=16, no 20','Opcion correcta','Si lado=10: perimetro=40, no 20','Si lado=20: perimetro=80']}},
  {id:'MT77',area:'matematicas',areaName:'Matematicas',difficulty:'media',question:`La fraccion 3/5 es equivalente a:`,options:['6/12','9/15','12/25','6/5'],correct:1,explanation:{correct:'3/5 = (3x3)/(5x3) = 9/15. Multiplicamos numerador y denominador por el mismo numero.',wrongs:['6/12 = 1/2, no 3/5','Opcion correcta','12/25 no es 3/5 (3x4=12 pero 5x5=25)','6/5 es mayor que 1']}},
  {id:'MT78',area:'matematicas',areaName:'Matematicas',difficulty:'dificil',question:`El area de un triangulo con base 10 cm y altura 6 cm es:`,options:['60 cm2','30 cm2','16 cm2','120 cm2'],correct:1,explanation:{correct:'Area del triangulo = (base x altura)/2 = (10 x 6)/2 = 60/2 = 30 cm2.',wrongs:['Eso seria 10x6 sin dividir por 2','Opcion correcta','Sumaste 10+6=16','Multiplicaste por 2 en lugar de dividir']}},
  {id:'MT79',area:'matematicas',areaName:'Matematicas',difficulty:'facil',question:`Cual de los siguientes es un numero compuesto?`,options:['2','3','5','9'],correct:3,explanation:{correct:'Un numero compuesto tiene mas de dos divisores. 9 = 3x3, tiene divisores 1, 3 y 9.',wrongs:['2 es primo (solo divisible por 1 y 2)','3 es primo','5 es primo','Opcion correcta']}},
  {id:'MT80',area:'matematicas',areaName:'Matematicas',difficulty:'media',question:`En un curso de 40 estudiantes, 15 son mujeres. Que porcentaje son hombres?`,options:['37.5%','62.5%','25%','75%'],correct:1,explanation:{correct:'Hombres = 40 - 15 = 25. Porcentaje = (25/40)x100% = 62.5%.',wrongs:['Ese es el % de mujeres (15/40)','Opcion correcta','Calculaste 10/40?','Calculaste 30/40?']}},
  {id:'MT81',area:'matematicas',areaName:'Matematicas',difficulty:'dificil',question:`La solucion del sistema: x + y = 10, x - y = 4 es:`,options:['x=7, y=3','x=6, y=4','x=8, y=2','x=5, y=5'],correct:0,explanation:{correct:'Sumando: 2x = 14 - x = 7. Sustituyendo: 7 + y = 10 - y = 3.',wrongs:['Opcion correcta','x=6,y=4: 6+4=10 bien, 6-4=2 no 4','x=8,y=2: 8+2=10 bien, 8-2=6 no 4','x=5,y=5: 5-5=0 no 4']}},
  {id:'MT82',area:'matematicas',areaName:'Matematicas',difficulty:'facil',question:`Cual es el resultado de v25 + v9?`,options:['8','34','5','3'],correct:0,explanation:{correct:'v25 = 5 y v9 = 3. Por tanto v25 + v9 = 5 + 3 = 8.',wrongs:['Opcion correcta','Sumaste 25+9=34?','Solo v25','Solo v9']}},
  {id:'MT83',area:'matematicas',areaName:'Matematicas',difficulty:'media',context:`Un terreno rectangular mide 20 m de largo y 15 m de ancho. Se desea construir una cerca alrededor.`,question:`Cuantos metros de cerca se necesitan?`,options:['300 m','70 m','35 m','60 m'],correct:1,explanation:{correct:'Perimetro = 2(largo + ancho) = 2(20+15) = 2x35 = 70 m.',wrongs:['Eso seria el area: 20x15=300','Opcion correcta','Eso seria 20+15=35 (medio perimetro)','Eso seria 2x15+20=50, incompleto']}},
  {id:'MT84',area:'matematicas',areaName:'Matematicas',difficulty:'dificil',question:`Cuantas diagonales tiene un pentagono?`,options:['3','5','7','10'],correct:1,explanation:{correct:'Numero de diagonales = n(n-3)/2 = 5(5-3)/2 = 5x2/2 = 5.',wrongs:['Un pentagono tiene 5 diagonales','Opcion correcta','Eso seria un heptagono','Eso seria un decagono']}},
  {id:'MT85',area:'matematicas',areaName:'Matematicas',difficulty:'facil',question:`Cuanto es 1/4 + 1/4?`,options:['1/8','1/2','1/16','2/4'],correct:1,explanation:{correct:'1/4 + 1/4 = (1+1)/4 = 2/4 = 1/2.',wrongs:['No se suman denominadores','Opcion correcta','1/4+1/4=1/2, no 1/16','2/4 se simplifica a 1/2']}},
  {id:'MT86',area:'matematicas',areaName:'Matematicas',difficulty:'media',question:`Si 5n = 125, entonces n es:`,options:['2','3','4','25'],correct:1,explanation:{correct:'53 = 5x5x5 = 125. Por tanto n = 3.',wrongs:['52 = 25, no 125','Opcion correcta','54 = 625, no 125','5x25 = 125, pero n es exponente, no factor']}},
  {id:'MT87',area:'matematicas',areaName:'Matematicas',difficulty:'dificil',question:`El rango del conjunto de datos: 12, 15, 18, 22, 27 es:`,options:['10','15','12','27'],correct:1,explanation:{correct:'Rango = valor maximo - valor minimo = 27 - 12 = 15.',wrongs:['Calculaste mal: 27-12=15','Opcion correcta','Esa es la media o mediana','Ese es el valor maximo']}},
  {id:'MT88',area:'matematicas',areaName:'Matematicas',difficulty:'facil',question:`La expresion 1 km equivale a:`,options:['10 m','100 m','1000 m','10000 m'],correct:2,explanation:{correct:'1 kilometro = 1000 metros.',wrongs:['1 km = 1000 m, no 10','1 km = 1000 m, no 100','Opcion correcta','1 km = 1000 m, no 10000']}},
  {id:'MT89',area:'matematicas',areaName:'Matematicas',difficulty:'media',question:`En una bolsa hay 4 canicas rojas, 3 azules y 5 verdes. Cual es la probabilidad de sacar una canica roja o verde?`,options:['1/3','1/2','3/4','4/5'],correct:2,explanation:{correct:'Total: 4+3+5=12. Rojas o verdes: 4+5=9. Probabilidad = 9/12 = 3/4.',wrongs:['Solo rojas son 4/12=1/3','Solo azules+rojas serian 7/12','Opcion correcta','Solo rojas+verdes=9/12=3/4, no 4/5']}},
  {id:'MT90',area:'matematicas',areaName:'Matematicas',difficulty:'dificil',question:`La funcion f(x) = 2x es un ejemplo de funcion:`,options:['Lineal','Cuadratica','Exponencial','Logaritmica'],correct:2,explanation:{correct:'2x es una funcion exponencial porque la variable independiente (x) esta en el exponente.',wrongs:['Lineal seria 2x','Cuadratica seria x2','Opcion correcta','Logaritmica seria log2(x)']}},
  {id:'MT91',area:'matematicas',areaName:'Matematicas',difficulty:'facil',question:`Redondea 3.78 al entero mas cercano:`,options:['3','3.7','4','3.8'],correct:2,explanation:{correct:'3.78: el digito decimal (7) es >= 5, por lo que redondeamos hacia arriba: 4.',wrongs:['3.78 redondea a 4 porque 7>=5','Eso es truncar a un decimal','Opcion correcta','Eso es redondear a un decimal']}},
  {id:'MT92',area:'matematicas',areaName:'Matematicas',difficulty:'media',question:`Cual es el valor de 23 x 22?`,options:['25 = 32','26 = 64','45 = 1024','21 = 2'],correct:0,explanation:{correct:'23 x 22 = 23+2 = 25 = 32. Cuando multiplicamos potencias de igual base, sumamos exponentes.',wrongs:['Opcion correcta','Sumarias exponentes 3+2=5, no 6','No se multiplican las bases','Se suman exponentes: 3+2=5']}},
  {id:'MT93',area:'matematicas',areaName:'Matematicas',difficulty:'dificil',question:`La distancia entre los puntos (-2, 1) y (3, 1) en el plano cartesiano es:`,options:['3','4','5','1'],correct:2,explanation:{correct:'d = v((3-(-2))2 + (1-1)2) = v(52 + 02) = v25 = 5. Como tienen misma coordenada y, la distancia es la diferencia de x: 3-(-2)=5.',wrongs:['Calculaste 3-2+1?','3-(-2)=5','Opcion correcta','Calculaste mal']}},
  {id:'MT94',area:'matematicas',areaName:'Matematicas',difficulty:'facil',question:`Cuanto es 7! (7 factorial)?`,options:['720','5040','2520','40320'],correct:1,explanation:{correct:'7! = 7x6x5x4x3x2x1 = 5040.',wrongs:['Eso es 6! = 720','Opcion correcta','Eso seria 7!/2','Eso es 8! = 40320']}},
  {id:'MT95',area:'matematicas',areaName:'Matematicas',difficulty:'media',question:`Un automovil viaja a 60 km/h. Cuanto tarda en recorrer 180 km?`,options:['1 hora','2 horas','3 horas','4 horas'],correct:2,explanation:{correct:'Tiempo = distancia/velocidad = 180/60 = 3 horas.',wrongs:['60 km en 1 hora, no 180','120 km en 2 horas','Opcion correcta','240 km en 4 horas']}},
  {id:'MT96',area:'matematicas',areaName:'Matematicas',difficulty:'dificil',question:`Cual es la tasa de interes simple si un capital de $100.000 genera $20.000 de interes en 2 anos?`,options:['5% anual','10% anual','15% anual','20% anual'],correct:1,explanation:{correct:'I = C x r x t - 20000 = 100000 x r x 2 - r = 20000/200000 = 0.10 = 10% anual.',wrongs:['Calculaste mal la tasa','Opcion correcta','Tasa muy alta','Tasa muy alta']}},
  {id:'MT97',area:'matematicas',areaName:'Matematicas',difficulty:'facil',question:`La diagonal de un cuadrado de lado 1 mide:`,options:['1','v2','2','v3'],correct:1,explanation:{correct:'Diagonal del cuadrado = lado x v2 = 1 x v2 = v2. Por Pitagoras: d2 = 12+12 = 2, d = v2.',wrongs:['La diagonal es mayor que el lado','Opcion correcta','Eso seria si el lado fuera v2','Esa es la diagonal de un cubo']}},
  {id:'MT98',area:'matematicas',areaName:'Matematicas',difficulty:'media',question:`La razon 2:5 es equivalente a:`,options:['4:10','5:2','1:3','3:7'],correct:0,explanation:{correct:'2:5 = 4:10 (multiplicando ambos terminos por 2). Las razones equivalentes mantienen la misma proporcion.',wrongs:['Opcion correcta','Esa es la razon inversa','2/5 != 1/3','2/5 != 3/7']}},
  {id:'MT99',area:'matematicas',areaName:'Matematicas',difficulty:'dificil',question:`El valor de sen(0) + cos(0) es:`,options:['0','1','2','No definido'],correct:1,explanation:{correct:'sen(0) = 0 y cos(0) = 1. Por tanto sen(0) + cos(0) = 0 + 1 = 1.',wrongs:['sen(0)=0, cos(0)=1, suma=1','Opcion correcta','sen(0)=0, cos(0)=1, suma no da 2','Si esta definido']}},
  {id:'MT100',area:'matematicas',areaName:'Matematicas',difficulty:'facil',question:`Un numero decimal periodico como 0.333... se puede expresar como:`,options:['1/3','3/10','33/100','1/30'],correct:0,explanation:{correct:'0.333... es la representacion decimal de 1/3. 1 / 3 = 0.333...',wrongs:['Opcion correcta','3/10 = 0.3 exacto','33/100 = 0.33 exacto','1/30 = 0.0333...']}},

  // ===== SOCIALES - BLOQUE 5 (SC60-SC99) =====
  {id:'SC60',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'media',question:`La "Revolucion Verde" de mediados del siglo XX consistio en:`,options:['La industrializacion de America Latina','El aumento de la productividad agricola mediante nuevas tecnologias y semillas','La Revolucion Francesa','La creacion de la ONU'],correct:1,explanation:{correct:'La Revolucion Verde fue un programa de aumento de productividad agricola usando semillas mejoradas, fertilizantes, pesticidas y maquinaria.',wrongs:['No fue industrializacion sino agricola','Opcion correcta','No es la Revolucion Francesa','No es sobre la ONU']}},
  {id:'SC61',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'facil',question:`La principal funcion de la Policia Nacional de Colombia es:`,options:['Administrar justicia','Mantener la seguridad y el orden publico','Recaudar impuestos','Crear leyes'],correct:1,explanation:{correct:'La Policia Nacional es un cuerpo armado de naturaleza civil, encargado de mantener la seguridad, el orden publico y la convivencia ciudadana.',wrongs:['La justicia la administra la Rama Judicial','Opcion correcta','Los impuestos los recauda la DIAN','Las leyes las crea el Congreso']}},
  {id:'SC62',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'dificil',question:`La "alianza del Pacifico" es un bloque de integracion regional conformado por:`,options:['Argentina, Brasil, Uruguay y Paraguay','Chile, Colombia, Mexico y Peru','Venezuela, Ecuador, Bolivia y Cuba','Estados Unidos, Canada y Mexico'],correct:1,explanation:{correct:'La Alianza del Pacifico fue creada en 2011 y la conforman Chile, Colombia, Mexico y Peru, con otros paises como observadores.',wrongs:['Ese es el Mercosur','Opcion correcta','No incluye a esos paises','Ese es el T-MEC']}},
  {id:'SC63',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'media',question:`El paramo es un ecosistema estrategico para Colombia porque:`,options:['Es ideal para la agricultura intensiva','Regula el agua y almacena carbono','Es el mejor lugar para construir ciudades','No tiene importancia ecologica'],correct:1,explanation:{correct:'Los paramos son estrategicos porque "regulan el agua" (son fuentes de rios) y "almacenan carbono" en sus suelos. Colombia tiene el 50% de los paramos del mundo.',wrongs:['Los paramos no son aptos para agricultura','Opcion correcta','No son aptos para construccion','Son ecologicamente vitales']}},
  {id:'SC64',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'facil',question:`El voto en Colombia es:`,options:['Opcional para todos','Un derecho y un deber ciudadano','Solo para mayores de 25 anos','Exclusivo para hombres'],correct:1,explanation:{correct:'El voto en Colombia es un derecho y un deber ciudadano (art. 258 Constitucion). Es obligatorio para mayores de 18 anos.',wrongs:['Tiene caracter obligatorio','Opcion correcta','Se vota desde los 18 anos','Hombres y mujeres votan']}},
  {id:'SC65',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'dificil',question:`La "curva de Phillips" en economia muestra una relacion inversa entre:`,options:['Inflacion y crecimiento','Desempleo e inflacion','Impuestos y recaudacion','Exportaciones e importaciones'],correct:1,explanation:{correct:'La Curva de Phillips muestra una relacion inversa entre desempleo e inflacion: cuando baja el desempleo, la inflacion tiende a subir.',wrongs:['No es sobre crecimiento','Opcion correcta','Esa es la Curva de Laffer','Esa es la balanza comercial']}},
  {id:'SC66',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'media',question:`La "Ley de Cuotas" en Colombia (Ley 581 de 2000) establece:`,options:['La eliminacion de impuestos para mujeres','Que al menos el 30% de los cargos publicos de alto nivel sean ocupados por mujeres','La obligatoriedad del voto femenino','La creacion de empresas exclusivas para mujeres'],correct:1,explanation:{correct:'La Ley 581 de 2000 establece que minimo el 30% de los cargos de maximo nivel decisorio en la administracion publica deben ser ocupados por mujeres.',wrongs:['No elimina impuestos','Opcion correcta','El voto femenino existe desde 1957','No crea empresas']}},
  {id:'SC67',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'facil',question:`El rio Magdalena es importante para Colombia porque:`,options:['Es el rio mas corto del pais','Es la principal via fluvial y atraviesa gran parte del territorio','Desemboca en el Pacifico','Separa Colombia de Venezuela'],correct:1,explanation:{correct:'El rio Magdalena es el principal rio de Colombia, nace en el Macizo Colombiano y desemboca en el Caribe. Es una importante via de transporte y fuente de energia.',wrongs:['Es uno de los mas largos','Opcion correcta','Desemboca en el Atlantico/Caribe','No es fronterizo']}},
  {id:'SC68',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'dificil',question:`El "GATT" (Acuerdo General sobre Aranceles y Comercio) fue reemplazado en 1995 por:`,options:['La OMC (Organizacion Mundial del Comercio)','El FMI (Fondo Monetario Internacional)','El Banco Mundial','La ONU'],correct:0,explanation:{correct:'El GATT, creado en 1947, fue reemplazado por la OMC (Organizacion Mundial del Comercio) en 1995, que tiene un alcance mas amplio.',wrongs:['Opcion correcta','El FMI se enfoca en estabilidad financiera','El Banco Mundial se enfoca en desarrollo','La ONU es mas general']}},
  {id:'SC69',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'media',question:`El "derecho a la vivienda digna" en Colombia esta consagrado en:`,options:['El Codigo Civil','La Constitucion Politica (art. 51)','El Codigo Penal','Las leyes de mercado'],correct:1,explanation:{correct:'El articulo 51 de la Constitucion de 1991 establece que "todos los colombianos tienen derecho a vivienda digna".',wrongs:['No esta en el Codigo Civil','Opcion correcta','No esta en el Codigo Penal','Es un derecho constitucional']}},
  {id:'SC70',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'facil',question:`La "Region Andina" de Colombia debe su nombre a:`,options:['El rio Andino','La cordillera de los Andes que la atraviesa','Una ciudad llamada Andes','Un explorador llamado Andino'],correct:1,explanation:{correct:'La Region Andina es la region atravesada por las tres cordilleras de los Andes (Occidental, Central y Oriental) y es la mas poblada del pais.',wrongs:['No hay rio Andino','Opcion correcta','No hay ciudad Andes en ese contexto','No es por un explorador']}},
  {id:'SC71',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'dificil',question:`El "Estado laico" significa que el Estado:`,options:['Tiene una religion oficial','Es neutral en materia religiosa y no favorece ninguna religion','Prohibe todas las religiones','Solo reconoce una iglesia'],correct:1,explanation:{correct:'El Estado laico es neutral en asuntos religiosos, no tiene religion oficial y garantiza la libertad de culto para todas las creencias.',wrongs:['Un Estado laico no tiene religion oficial','Opcion correcta','Garantiza la libertad religiosa','Reconoce la pluralidad religiosa']}},
  {id:'SC72',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'media',question:`La "exploracion y explotacion de hidrocarburos" en Colombia es regulada por:`,options:['La DIAN','La ANH (Agencia Nacional de Hidrocarburos)','La SAC','El DANE'],correct:1,explanation:{correct:'La ANH (Agencia Nacional de Hidrocarburos) es la entidad encargada de administrar los recursos hidrocarburiferos del pais.',wrongs:['La DIAN recauda impuestos','Opcion correcta','La SAC es de agricultura','El DANE hace estadisticas']}},
  {id:'SC73',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'facil',question:`La "Audiencia Publica" es un mecanismo de participacion donde:`,options:['Los ciudadanos son juzgados','Las autoridades rinden cuentas y discuten temas con la comunidad','Solo hablan los funcionarios','Se realizan elecciones'],correct:1,explanation:{correct:'La audiencia publica es un espacio donde "las autoridades rinden cuentas y discuten temas" con la comunidad, permitiendo la participacion ciudadana.',wrongs:['No es un espacio judicial','Opcion correcta','Los ciudadanos tambien participan','No es una eleccion']}},
  {id:'SC74',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'dificil',question:`La "tasa de cambio" representa:`,options:['La inflacion del pais','El valor de una moneda expresado en otra moneda','La tasa de interes del banco central','El PIB per capita'],correct:1,explanation:{correct:'La tasa de cambio (o tipo de cambio) es "el valor de una moneda expresado en otra moneda", por ejemplo cuantos pesos vale un dolar.',wrongs:['La inflacion mide aumento de precios','Opcion correcta','La tasa de interes es el costo del dinero','El PIB per capita es ingreso por persona']}},
  {id:'SC75',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'media',question:`El "derecho de reunion" en Colombia permite:`,options:['Reunirse solo con permiso del gobierno','Reunirse pacificamente sin necesidad de permiso previo','Reunirse solo para actividades religiosas','No existe este derecho'],correct:1,explanation:{correct:'El derecho de reunion (art. 37 Constitucion) permite reunirse pacificamente sin permiso previo, aunque en espacios publicos puede requerirse aviso.',wrongs:['No se necesita permiso para reuniones pacificas','Opcion correcta','Aplica para todo tipo de reuniones','Si existe como derecho fundamental']}},
  {id:'SC76',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'facil',question:`Colombia tiene costas en dos oceanos:`,options:['Atlantico y Pacifico','Indico y Pacifico','Atlantico y Artico','Pacifico y Antartico'],correct:0,explanation:{correct:'Colombia tiene costas en el oceano Atlantico (mar Caribe, al norte) y en el oceano Pacifico (al occidente).',wrongs:['Opcion correcta','No tiene costa en el Indico','No tiene costa en el Artico','No tiene costa en el Antartico']}},
  {id:'SC77',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'dificil',question:`La "balanza de pagos" de un pais registra:`,options:['Solo las exportaciones','Todas las transacciones economicas con el exterior','Los impuestos internos','El gasto publico'],correct:1,explanation:{correct:'La balanza de pagos registra "todas las transacciones economicas con el exterior" de un pais: exportaciones, importaciones, inversiones, transferencias.',wrongs:['Registra mas que exportaciones','Opcion correcta','No registra impuestos internos','No es el gasto publico']}},
  {id:'SC78',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'media',question:`La "Corte Penal Internacional" (CPI) tiene competencia para juzgar:`,options:['Todos los delitos comunes','Genocidio, crimenes de lesa humanidad, crimenes de guerra y agresion','Delitos fiscales','Crimenes de transito'],correct:1,explanation:{correct:'La CPI juzga los crimenes mas graves para la comunidad internacional: genocidio, crimenes de lesa humanidad, crimenes de guerra y crimen de agresion.',wrongs:['Solo los delitos mas graves internacionalmente','Opcion correcta','No juzga delitos fiscales','No juzga delitos de transito']}},
  {id:'SC79',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'facil',question:`El "DANE" es la entidad encargada de:`,options:['Administrar la justicia','Producir las estadisticas oficiales de Colombia','Emitir la moneda','Conducir la politica exterior'],correct:1,explanation:{correct:'El DANE (Departamento Administrativo Nacional de Estadistica) es la entidad encargada de producir y difundir las estadisticas oficiales del pais.',wrongs:['La justicia es funcion de la Rama Judicial','Opcion correcta','La moneda la emite el Banco de la Republica','La politica exterior es de Cancilleria']}},
  {id:'SC80',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'dificil',question:`El "constitucionalismo" como doctrina politica sostiene que:`,options:['El poder del Estado es ilimitado','El poder del Estado debe estar limitado por una constitucion','La monarquia es la mejor forma de gobierno','Las leyes no son necesarias'],correct:1,explanation:{correct:'El constitucionalismo establece que el poder del Estado debe estar limitado por una constitucion que garantice derechos fundamentales y la separacion de poderes.',wrongs:['El constitucionalismo LIMITA el poder','Opcion correcta','No se limita a la monarquia','Las leyes son fundamentales']}},
  {id:'SC81',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'media',context:`"Segun la OIT, en Colombia la tasa de desempleo juvenil (15-24 anos) duplica la tasa de desempleo general."`,question:`El texto indica que el desempleo juvenil en Colombia:`,options:['Es menor que el general','Duplica la tasa de desempleo general','Es igual al general','No existe'],correct:1,explanation:{correct:'El desempleo juvenil "duplica la tasa de desempleo general", lo que indica una situacion mas critica para los jovenes.',wrongs:['Es mayor, no menor','Opcion correcta','Es el doble, no igual','Si existe y es significativo']}},
  {id:'SC82',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'facil',question:`La "libertad de expresion" en Colombia es:`,options:['Un derecho limitado solo a periodistas','Un derecho fundamental de todas las personas','Inexistente','Solo para redes sociales'],correct:1,explanation:{correct:'La libertad de expresion es un derecho fundamental (art. 20 Constitucion) que tienen todas las personas para expresar y difundir su pensamiento.',wrongs:['Es un derecho de TODAS las personas','Opcion correcta','Si existe como derecho constitucional','Aplica a todos los medios']}},
  {id:'SC83',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'dificil',question:`La "descentralizacion" en Colombia implica:`,options:['La concentracion del poder en el gobierno central','La transferencia de competencias y recursos a entidades territoriales','La eliminacion de los departamentos','La centralizacion de la educacion'],correct:1,explanation:{correct:'La descentralizacion transfiere "competencias y recursos" a entidades territoriales (departamentos, municipios) para que gestionen servicios publicos localmente.',wrongs:['Descentralizacion = distribuir, no concentrar','Opcion correcta','Los departamentos se fortalecen','La educacion es descentralizada']}},
  {id:'SC84',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'media',question:`El "censo de poblacion" en Colombia se realiza cada:`,options:['5 anos','10 anos','15 anos','20 anos'],correct:1,explanation:{correct:'El censo de poblacion en Colombia se realiza aproximadamente cada 10 anos. El DANE es la entidad encargada.',wrongs:['Los censos son cada 10 anos','Opcion correcta','No son cada 15','No son cada 20']}},
  {id:'SC85',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'facil',question:`La "independencia de Panama" de Colombia ocurrio en:`,options:['1903','1910','1899','1920'],correct:0,explanation:{correct:'Panama se separo de Colombia el 3 de noviembre de 1903, tras la Guerra de los Mil Dias y el rechazo del Tratado Herran-Hay.',wrongs:['Opcion correcta','No fue en 1910','No fue en 1899','No fue en 1920']}},
  {id:'SC86',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'dificil',question:`La "renta basica universal" es una propuesta que consiste en:`,options:['Dar trabajo a todos los ciudadanos','Un pago periodico del Estado a todos los ciudadanos sin condiciones','Reducir todos los impuestos a cero','Eliminar los subsidios existentes'],correct:1,explanation:{correct:'La renta basica universal propone "un pago periodico del Estado a todos los ciudadanos sin condiciones", independientemente de su situacion laboral.',wrongs:['No es un programa de empleo','Opcion correcta','No elimina impuestos','Podria complementar subsidios']}},
  {id:'SC87',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'media',question:`La "Comision Europea" es el organo ejecutivo de:`,options:['La ONU','La Union Europea','La OTAN','El Mercosur'],correct:1,explanation:{correct:'La Comision Europea es el organo ejecutivo de la Union Europea, encargada de proponer legislacion, implementar decisiones y velar por los tratados.',wrongs:['La ONU tiene su propio sistema','Opcion correcta','La OTAN es defensa militar','El Mercosur tiene su propia estructura']}},
  {id:'SC88',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'facil',question:`El "correo electronico" es un servicio que permite:`,options:['Hacer llamadas telefonicas','Enviar y recibir mensajes digitales','Navegar por internet','Comprar en linea'],correct:1,explanation:{correct:'El correo electronico (e-mail) permite "enviar y recibir mensajes digitales" a traves de internet.',wrongs:['Las llamadas son otro servicio','Opcion correcta','Navegar es funcion del navegador','Comprar es comercio electronico']}},
  {id:'SC89',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'dificil',question:`El "federalismo" es un sistema de organizacion estatal donde:`,options:['El poder central concentra todas las competencias','Existen niveles de gobierno con autonomia politica y administrativa','No existen estados o provincias','El poder lo ejerce un solo funcionario'],correct:1,explanation:{correct:'El federalismo distribuye el poder entre un gobierno central y unidades territoriales (estados, provincias) que tienen autonomia.',wrongs:['Eso seria un Estado unitario centralizado','Opcion correcta','Si existen divisiones territoriales autonomas','El poder se distribuye']}},
  {id:'SC90',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'media',question:`La "reforestacion" es importante porque:`,options:['Aumenta la desertificacion','Ayuda a recuperar ecosistemas, capturar carbono y prevenir erosion','Reduce la biodiversidad','Consume agua innecesariamente'],correct:1,explanation:{correct:'La reforestacion "ayuda a recuperar ecosistemas, capturar carbono y prevenir la erosion" del suelo.',wrongs:['Reduce la desertificacion','Opcion correcta','Aumenta la biodiversidad','Ayuda a conservar el agua']}},
  {id:'SC91',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'facil',question:`La "moneda digital" o criptomoneda mas conocida es:`,options:['El dolar','Bitcoin','El euro','El peso'],correct:1,explanation:{correct:'Bitcoin es la criptomoneda mas conocida, creada en 2009. Es una moneda digital descentralizada.',wrongs:['El dolar es moneda fiduciaria','Opcion correcta','El euro es moneda fiduciaria','El peso es moneda fiduciaria']}},
  {id:'SC92',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'dificil',question:`El "soft power" (poder blando) en relaciones internacionales se refiere a:`,options:['El poder militar de un pais','La capacidad de influir mediante cultura, valores e ideologia','El poder economico exclusivamente','La imposicion por la fuerza'],correct:1,explanation:{correct:'El "soft power" (Joseph Nye) es "la capacidad de influir mediante cultura, valores e ideologia", sin coercion.',wrongs:['Eso es "hard power" militar','Opcion correcta','No solo economia, tambien valores y cultura','No usa fuerza']}},
  {id:'SC93',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'media',question:`La "Cumbre de las Americas" es un evento donde:`,options:['Se reunen los presidentes de America para discutir temas regionales','Se realiza un concurso de belleza','Se disputan partidos de futbol','Se premia a cientificos'],correct:0,explanation:{correct:'La Cumbre de las Americas reune a "los presidentes de America para discutir temas regionales" como comercio, democracia y desarrollo.',wrongs:['Opcion correcta','No es concurso de belleza','No es deportivo','No es cientifico']}},
  {id:'SC94',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'facil',question:`El "derecho a la salud" en Colombia se garantiza mediante:`,options:['El pago directo del paciente','El Sistema General de Seguridad Social en Salud (SGSSS)','La caridad privada','Seguros internacionales'],correct:1,explanation:{correct:'El derecho a la salud se garantiza a traves del SGSSS, que incluye los regimenes contributivo y subsidiado.',wrongs:['Es un derecho garantizado por el Estado','Opcion correcta','No depende de la caridad','Los seguros internacionales son adicionales']}},
  {id:'SC95',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'dificil',question:`El "populismo punitivo" es una estrategia politica que:`,options:['Reduce las penas para delincuentes','Propone penas mas duras para ganar popularidad, sin basarse en evidencia','Elimina el sistema carcelario','Fortalece la rehabilitacion'],correct:1,explanation:{correct:'El populismo punitivo propone "penas mas duras para ganar popularidad" apelando al miedo, sin evidencia de que reduzca la criminalidad.',wrongs:['Propone aumentar penas','Opcion correcta','No elimina carceles','Se enfoca en castigo, no rehabilitacion']}},
  {id:'SC96',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'media',question:`La "media filiacion" es un sistema de identificacion que se basa en:`,options:['El ADN','Las huellas dactilares y caracteristicas fisicas','La firma digital','El numero de cedula'],correct:1,explanation:{correct:'La media filiacion identifica a una persona por "huellas dactilares y caracteristicas fisicas" como estatura, color de ojos, etc.',wrongs:['El ADN es identificacion genetica','Opcion correcta','La firma digital es electronica','La cedula es el documento']}},
  {id:'SC97',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'facil',question:`El "transporte publico" se caracteriza por:`,options:['Ser de uso exclusivo del gobierno','Estar disponible para todas las personas que paguen el pasaje','Ser gratuito siempre','Ser solo para turistas'],correct:1,explanation:{correct:'El transporte publico "esta disponible para todas las personas que paguen el pasaje", operando en rutas y horarios establecidos.',wrongs:['Esta disponible para todos','Opcion correcta','No siempre es gratuito','Es para todos los ciudadanos']}},
  {id:'SC98',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'dificil',question:`La "geopolitica" estudia:`,options:['La geografia fisica de los continentes','La influencia de la geografia en las relaciones de poder entre Estados','El clima de las regiones','La poblacion mundial'],correct:1,explanation:{correct:'La geopolitica estudia "la influencia de la geografia en las relaciones de poder entre Estados".',wrongs:['La geografia fisica es descriptiva','Opcion correcta','El clima es parte de la geografia','La poblacion es demografia']}},
  {id:'SC99',area:'sociales',areaName:'Sociales y Ciudadania',difficulty:'media',question:`La "accion de grupo" en Colombia permite:`,options:['Demandar individualmente','Que un grupo de personas afectadas por un mismo hecho demande colectivamente','Solo al gobierno demandar','Demandar sin pruebas'],correct:1,explanation:{correct:'La accion de grupo (art. 88 Constitucion) permite que "un grupo de personas afectadas por un mismo hecho demande colectivamente" para obtener reparacion.',wrongs:['Es colectiva, no individual','Opcion correcta','Cualquier grupo puede demandar','Requiere pruebas del dano']}},

  // ===== CIENCIAS NATURALES - BLOQUE 5 (CN62-CN101) =====
  {id:'CN62',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'media',question:`La capa de ozono protege la Tierra al absorber:`,options:['La luz visible','La radiacion ultravioleta del Sol','El calor de la Tierra','Los rayos X'],correct:1,explanation:{correct:'La capa de ozono en la estratosfera absorbe la mayor parte de la radiacion ultravioleta (UV) del Sol.',wrongs:['La luz visible la deja pasar','Opcion correcta','No absorbe el calor terrestre','No absorbe rayos X']}},
  {id:'CN63',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'facil',question:`Cual de los siguientes es un animal invertebrado?`,options:['Perro','Mariposa','Tiburon','Serpiente'],correct:1,explanation:{correct:'La mariposa es un insecto, por lo tanto es invertebrada (no tiene columna vertebral).',wrongs:['Los perros son vertebrados','Opcion correcta','Los tiburones son vertebrados','Las serpientes son vertebradas']}},
  {id:'CN64',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'dificil',question:`La unidad de medida de la frecuencia en el SI es:`,options:['Newton','Joule','Hercio (Hz)','Watts'],correct:2,explanation:{correct:'La frecuencia se mide en hercios (Hz), que equivale a 1/s (ciclos por segundo).',wrongs:['Newton mide fuerza','Joule mide energia','Opcion correcta','Watts mide potencia']}},
  {id:'CN65',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'media',question:`Las enzimas son proteinas que:`,options:['Almacenan energia','Catalizan reacciones quimicas en los seres vivos','Transportan oxigeno','Forman los huesos'],correct:1,explanation:{correct:'Las enzimas son "proteinas que catalizan reacciones quimicas", acelerandolas sin consumirse en el proceso.',wrongs:['Las grasas almacenan energia','Opcion correcta','Los globulos rojos transportan oxigeno','El calcio forma los huesos']}},
  {id:'CN66',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'facil',question:`El punto de fusion del hielo (agua solida) es:`,options:['-10C','0C','100C','50C'],correct:1,explanation:{correct:'El punto de fusion del hielo es 0C (a presion de 1 atm).',wrongs:['-10C esta por debajo del punto de fusion','Opcion correcta','100C es el punto de ebullicion','50C es temperatura ambiente alta']}},
  {id:'CN67',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'dificil',question:`La segunda ley de la termodinamica establece que:`,options:['La energia se conserva','La entropia de un sistema aislado siempre aumenta','El calor fluye del frio al calor','La energia puede crearse'],correct:1,explanation:{correct:'La segunda ley dice que "la entropia de un sistema aislado siempre aumenta" con el tiempo.',wrongs:['Esa es la primera ley','Opcion correcta','El calor fluye del caliente al frio','La energia no se crea ni destruye']}},
  {id:'CN68',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'media',question:`Los cloroplastos son orgánulos donde ocurre:`,options:['La respiracion celular','La fotosintesis','La sintesis de proteinas','La division celular'],correct:1,explanation:{correct:'Los cloroplastos son los orgánulos donde ocurre la fotosintesis. Contienen clorofila.',wrongs:['La respiracion ocurre en mitocondrias','Opcion correcta','La sintesis de proteinas en ribosomas','La division celular en el nucleo']}},
  {id:'CN69',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'facil',question:`Cual de los siguientes es un gas noble?`,options:['Oxigeno','Nitrogeno','Neon','Cloro'],correct:2,explanation:{correct:'El neon (Ne) es un gas noble (grupo 18), caracterizado por ser inerte y tener su capa de valencia completa.',wrongs:['El oxigeno es del grupo 16','El nitrogeno es del grupo 15','Opcion correcta','El cloro es del grupo 17']}},
  {id:'CN70',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'dificil',question:`La velocidad del sonido en el aire a 20C es aproximadamente:`,options:['343 m/s','343 km/h','1000 m/s','150 m/s'],correct:0,explanation:{correct:'La velocidad del sonido en el aire a 20C es aproximadamente 343 m/s (unos 1235 km/h).',wrongs:['Opcion correcta','343 km/h seria mucho menor','Eso seria en solidos','Demasiado baja']}},
  {id:'CN71',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'media',question:`El "ciclo del nitrogeno" es importante porque:`,options:['El nitrogeno es toxico para las plantas','El nitrogeno es esencial para proteinas y ADN, pero debe ser fijado','El nitrogeno no se encuentra en la atmosfera','Las plantas no necesitan nitrogeno'],correct:1,explanation:{correct:'El nitrogeno es esencial para proteinas y ADN, pero las plantas solo pueden usarlo en formas fijadas.',wrongs:['El nitrogeno no es toxico, es esencial','Opcion correcta','El N2 es ~78% de la atmosfera','Todas las plantas necesitan nitrogeno']}},
  {id:'CN72',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'facil',question:`El "Big Bang" es la teoria que explica:`,options:['El origen de la vida en la Tierra','El origen del universo a partir de una gran explosion','La formacion de las montanas','La extincion de los dinosaurios'],correct:1,explanation:{correct:'La teoria del Big Bang explica "el origen del universo a partir de una gran explosion" hace ~13.800 millones de anos.',wrongs:['El origen de la vida es la abiogenesis','Opcion correcta','Las montanas se forman por tectonica','Los dinosaurios se extinguieron por un asteroide']}},
  {id:'CN73',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'dificil',question:`El "principio de exclusion de Pauli" establece que:`,options:['Dos electrones pueden tener los mismos numeros cuanticos','Dos electrones en un atomo no pueden tener los mismos cuatro numeros cuanticos','Los electrones siempre estan en pares','Los protones y neutrones se excluyen'],correct:1,explanation:{correct:'Pauli dice que "dos electrones en un atomo no pueden tener los mismos cuatro numeros cuanticos".',wrongs:['El principio establece que NO pueden','Opcion correcta','No es sobre pares','Aplica a electrones']}},
  {id:'CN74',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'media',question:`La "presion atmosferica" al nivel del mar es aproximadamente:`,options:['1 atm','10 atm','0.1 atm','100 atm'],correct:0,explanation:{correct:'La presion atmosferica al nivel del mar es aproximadamente 1 atmosfera (atm) = 101.325 Pa.',wrongs:['Opcion correcta','10 atm seria a 100m de profundidad','Demasiado baja','Demasiado alta']}},
  {id:'CN75',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'facil',question:`La funcion de las raices de las plantas es:`,options:['Fotosintesis','Absorber agua y nutrientes del suelo','Producir flores','Realizar la polinizacion'],correct:1,explanation:{correct:'Las raices "absorben agua y nutrientes del suelo" y anclan la planta al sustrato.',wrongs:['La fotosintesis ocurre en las hojas','Opcion correcta','Las flores son estructuras reproductivas','La polinizacion la realizan insectos o viento']}},
  {id:'CN76',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'dificil',question:`La "constante de Planck" (h) tiene un valor de aproximadamente:`,options:['6.626 x 10-34 J·s','3 x 108 m/s','9.8 m/s2','1.6 x 10-19 C'],correct:0,explanation:{correct:'La constante de Planck es h ~ 6.626 x 10-34 J·s, fundamental en mecanica cuantica.',wrongs:['Opcion correcta','Esa es la velocidad de la luz','Esa es la aceleracion gravitacional','Esa es la carga del electron']}},
  {id:'CN77',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'media',question:`La "reaccion en cadena de la polimerasa" (PCR) se utiliza para:`,options:['Digestion de alimentos','Amplificar (copiar) fragmentos de ADN','Producir energia','Fabricar medicamentos'],correct:1,explanation:{correct:'La PCR es una tecnica molecular que "amplifica (copia) fragmentos de ADN" millones de veces.',wrongs:['No es digestion','Opcion correcta','No produce energia','Se usa para diagnosticar, no fabricar']}},
  {id:'CN78',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'facil',question:`Los "carbohidratos" son nutrientes que proporcionan principalmente:`,options:['Proteinas','Energia al cuerpo','Vitaminas','Minerales'],correct:1,explanation:{correct:'Los carbohidratos (glucidos) son la principal fuente "de energia al cuerpo".',wrongs:['Las proteinas son estructurales','Opcion correcta','Las vitaminas son reguladoras','Los minerales son reguladores']}},
  {id:'CN79',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'dificil',question:`El "punto cuantico" (quantum dot) es:`,options:['Un tipo de estrella','Una nanoparticula semiconductora con propiedades opticas especiales','Un agujero negro pequeno','Un tipo de bacteria'],correct:1,explanation:{correct:'Un "punto cuantico" es una nanoparticula semiconductora que emite luz de diferentes colores segun su tamano.',wrongs:['No es una estrella','Opcion correcta','No es un agujero negro','No es un organismo']}},
  {id:'CN80',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'media',question:`La "seleccion sexual" es un tipo de seleccion natural donde:`,options:['Los organismos compiten por reproducirse, y ciertos rasgos aumentan el exito reproductivo','Los organismos eligen su habitat','Las especies migran','Los organismos cambian de color'],correct:0,explanation:{correct:'La seleccion sexual (Darwin) ocurre cuando "ciertos rasgos aumentan el exito reproductivo".',wrongs:['Opcion correcta','No es seleccion de habitat','No es migracion','El color puede ser un rasgo seleccionado sexualmente']}},
  {id:'CN81',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'facil',question:`La "osmosis" es el paso de agua a traves de una membrana:`,options:['Siempre hacia afuera de la celula','Desde donde hay menos solutos hacia donde hay mas','Solo en plantas','En una sola direccion irreversible'],correct:1,explanation:{correct:'La osmosis es el paso de agua desde donde hay menos solutos hacia donde hay mas (de menor a mayor concentracion).',wrongs:['Depende de la concentracion de solutos','Opcion correcta','Ocurre en todas las celulas','Es reversible']}},
  {id:'CN82',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'dificil',question:`La "fision binaria" es el proceso de reproduccion de:`,options:['Los mamiferos','Las bacterias','Las aves','Los reptiles'],correct:1,explanation:{correct:'La fision binaria es la reproduccion asexual de "las bacterias", donde una celula se divide en dos celulas hijas identicas.',wrongs:['Los mamiferos se reproducen sexualmente','Opcion correcta','Las aves ponen huevos','Los reptiles ponen huevos']}},
  {id:'CN83',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'media',question:`La "densidad" se define como:`,options:['Masa x volumen','Masa / volumen','Volumen / masa','Masa + volumen'],correct:1,explanation:{correct:'La densidad (r) es "masa/volumen" (m/V). Se mide en kg/m3 o g/cm3.',wrongs:['Eso da masa, no densidad','Opcion correcta','Eso seria el inverso de la densidad','No es una suma']}},
  {id:'CN84',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'facil',question:`El "fosforo" es importante para los seres vivos porque:`,options:['Forma parte del ADN y los huesos','Es el principal combustible del cuerpo','Da color a las plantas','No tiene funcion biologica'],correct:0,explanation:{correct:'El fosforo (P) es componente esencial del ADN, ARN, ATP y los huesos (fosfato de calcio).',wrongs:['Opcion correcta','Los carbohidratos son combustibles','La clorofila da color verde','Si tiene funciones vitales']}},
  {id:'CN85',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'dificil',question:`La "interferencia" es un fenomeno ondulatorio que ocurre cuando:`,options:['Dos ondas se anulan completamente siempre','Dos o mas ondas se superponen y combinan sus amplitudes','Una onda cambia de medio','Una onda se refleja'],correct:1,explanation:{correct:'La interferencia ocurre cuando "dos o mas ondas se superponen y combinan sus amplitudes".',wrongs:['Puede ser constructiva o destructiva','Opcion correcta','Eso seria refraccion','Eso seria reflexion']}},
  {id:'CN86',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'media',question:`Las "celulas madre" se caracterizan por:`,options:['Ser celulas especializadas','Poder diferenciarse en varios tipos celulares y autorrenovarse','No poder dividirse','Ser resistentes a antibioticos'],correct:1,explanation:{correct:'Las celulas madre pueden "diferenciarse en varios tipos celulares" y "autorrenovarse".',wrongs:['Son celulas no especializadas','Opcion correcta','Si pueden dividirse','No son necesariamente resistentes']}},
  {id:'CN87',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'facil',question:`La "lluvia" es una forma de:`,options:['Precipitacion','Evaporacion','Condensacion','Sublimacion'],correct:0,explanation:{correct:'La lluvia es "precipitacion" de agua liquida desde las nubes hacia la superficie terrestre.',wrongs:['Opcion correcta','La evaporacion sube el agua a las nubes','La condensacion forma las nubes','La sublimacion es solido a gas']}},
  {id:'CN88',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'dificil',question:`La "relatividad especial" de Einstein se basa en el postulado de que:`,options:['La velocidad de la luz es constante para todos los observadores','El tiempo es absoluto','La gravedad es una fuerza','La masa no depende de la velocidad'],correct:0,explanation:{correct:'Un postulado clave de la relatividad especial es que "la velocidad de la luz es constante para todos los observadores".',wrongs:['Opcion correcta','El tiempo es relativo','La gravedad es curvatura del espacio-tiempo','La masa relativista aumenta con la velocidad']}},
  {id:'CN89',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'media',question:`La "homeostasis" es la capacidad de:`,options:['Mantenerse en equilibrio interno a pesar de cambios externos','Reproducirse rapidamente','Moverse activamente','Cambiar de forma'],correct:0,explanation:{correct:'La homeostasis es "la capacidad de mantener el equilibrio interno" (temperatura, pH, glucosa) a pesar de cambios externos.',wrongs:['Opcion correcta','No es reproduccion','No es movimiento','No es cambio de forma']}},
  {id:'CN90',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'facil',question:`La "combustion" es una reaccion quimica que requiere:`,options:['Agua y dioxido de carbono','Oxigeno y un combustible','Nitrogeno y helio','Luz y calor solo'],correct:1,explanation:{correct:'La combustion requiere "oxigeno y un combustible" (material que arde), produciendo calor y luz.',wrongs:['El agua apaga el fuego','Opcion correcta','El nitrogeno no es reactivo en combustion','Solo el calor no basta sin oxigeno']}},
  {id:'CN91',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'dificil',question:`Los "bosones" son particulas que:`,options:['Componen la materia','Transmiten las fuerzas fundamentales','Son las mas pesadas','No existen'],correct:1,explanation:{correct:'Los bosones son "particulas que transmiten las fuerzas fundamentales" (foton, gluon, W, Z, Higgs).',wrongs:['Los fermiones componen la materia','Opcion correcta','Varian en masa segun el tipo','Si existen (descubiertos experimentalmente)']}},
  {id:'CN92',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'media',question:`La "clorofila" es el pigmento que da color verde a las plantas y:`,options:['Absorbe luz para la fotosintesis','Protege contra insectos','Almacena agua','Produce flores'],correct:0,explanation:{correct:'La clorofila "absorbe luz (principalmente roja y azul) para la fotosintesis", reflejando la luz verde.',wrongs:['Opcion correcta','Los compuestos secundarios protegen','La vacuola almacena agua','Los genes controlan la floracion']}},
  {id:'CN93',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'facil',question:`La "gravedad" en la superficie de la Tierra es aproximadamente:`,options:['9.8 m/s2','10 km/s2','1 m/s2','100 m/s2'],correct:0,explanation:{correct:'La aceleracion de la gravedad en la superficie terrestre es g ~ 9.8 m/s2.',wrongs:['Opcion correcta','Demasiado alta','Demasiado baja','Demasiado alta']}},
  {id:'CN94',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'dificil',question:`El "cobre" es un metal que se caracteriza por:`,options:['Ser aislante electrico','Ser buen conductor electrico y termico','Ser liquido a temperatura ambiente','No oxidarse nunca'],correct:1,explanation:{correct:'El cobre (Cu) es un excelente "conductor electrico y termico", ampliamente usado en cableado electrico.',wrongs:['Es excelente conductor, no aislante','Opcion correcta','Es solido a temperatura ambiente','Si se oxida (forma patina)']}},
  {id:'CN95',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'media',question:`La "drogodependencia" es una enfermedad que afecta:`,options:['Solo al sistema respiratorio','El sistema nervioso central, causando dependencia fisica y psicologica','Solo al higado','Exclusivamente a los jovenes'],correct:1,explanation:{correct:'La drogodependencia "afecta el sistema nervioso central", generando dependencia fisica y psicologica.',wrongs:['Afecta principalmente el sistema nervioso','Opcion correcta','El higado metaboliza, no es el principal afectado','Afecta a todas las edades']}},
  {id:'CN96',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'facil',question:`La "estrella mas cercana" a la Tierra (despues del Sol) es:`,options:['La Luna','Proxima Centauri','Sirius','Alpha Centauri'],correct:1,explanation:{correct:'Proxima Centauri es la estrella mas cercana al Sol, a unos 4.2 anos luz de distancia.',wrongs:['La Luna es un satelite, no una estrella','Opcion correcta','Sirius esta a 8.6 anos luz','Alpha Centauri es un sistema triple']}},
  {id:'CN97',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'dificil',question:`La "cromatografia" es una tecnica que permite:`,options:['Medir la temperatura','Separar los componentes de una mezcla','Pesar sustancias','Calentar reacciones'],correct:1,explanation:{correct:'La cromatografia "separa los componentes de una mezcla" basandose en su diferente afinidad por fases.',wrongs:['La temperatura se mide con termometro','Opcion correcta','Las balanzas pesan','El mechero calienta']}},
  {id:'CN98',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'media',question:`La "simbiosis" es una relacion entre dos organismos donde:`,options:['Uno se beneficia y el otro es perjudicado','Ambos se benefician (mutualismo)','Siempre es negativa','No hay interaccion'],correct:1,explanation:{correct:'La simbiosis en sentido estricto (mutualismo) es donde "ambos se benefician", como liquenes.',wrongs:['Eso es parasitismo','Opcion correcta','Hay tipos positivos y negativos','Si hay interaccion cercana']}},
  {id:'CN99',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'facil',question:`La "electricidad estatica" se produce por:`,options:['El flujo continuo de electrones','La acumulacion de carga electrica en un objeto','El movimiento de protones','La friccion que genera calor'],correct:1,explanation:{correct:'La electricidad estatica se produce por "la acumulacion de carga electrica en un objeto".',wrongs:['Eso es corriente electrica','Opcion correcta','Los protones no se mueven libremente','La friccion puede generar estatica']}},
  {id:'CN100',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'dificil',question:`La "energia nuclear" se obtiene mediante:`,options:['Reacciones quimicas','Reacciones de fision o fusion del nucleo atomico','Combustion de carbon','Energia solar'],correct:1,explanation:{correct:'La energia nuclear se obtiene de "reacciones de fision o fusion del nucleo atomico" (E=mc2).',wrongs:['Las reacciones quimicas implican electrones','Opcion correcta','El carbon es energia quimica','La solar es energia electromagnetica']}},
  {id:'CN101',area:'ciencias',areaName:'Ciencias Naturales',difficulty:'media',question:`Las "hormonas" son mensajeros quimicos que:`,options:['Se producen en el sistema digestivo','Son producidas por glandulas endocrinas y regulan funciones corporales','Solo actuan en el cerebro','No tienen efectos en el cuerpo'],correct:1,explanation:{correct:'Las hormonas son "producidas por glandulas endocrinas" y viajan por la sangre para "regular funciones corporales".',wrongs:['Las glandulas endocrinas las producen','Opcion correcta','Actuan en todo el cuerpo','Tienen efectos especificos']}},

  // ===== INGLES - BLOQUE 5 (EN61-EN100) =====
  {id:'EN61',area:'ingles',areaName:'Ingles',difficulty:'facil',context:`"I ___ to music every day."`,question:`Choose the correct verb form:`,options:['listen','listens','listened','listening'],correct:0,explanation:{correct:'Present simple for habitual actions. With "I", use the base form: "I listen to music every day."',wrongs:['Opcion correcta','"Listens" is third person singular','"Listened" is past tense','"Listening" needs a helper verb']}},
  {id:'EN62',area:'ingles',areaName:'Ingles',difficulty:'media',context:`"She ___ her homework before dinner yesterday."`,question:`Choose the correct verb form:`,options:['finish','finishes','finished','finishing'],correct:2,explanation:{correct:'"Yesterday" indicates past time. Past simple: "She FINISHED her homework before dinner."',wrongs:['"Finish" is present','"Finishes" is present third person','Opcion correcta','"Finishing" needs a helper']}},
  {id:'EN63',area:'ingles',areaName:'Ingles',difficulty:'dificil',context:`"I wish I ___ buy a new car, but I don't have enough money."`,question:`Choose the correct option:`,options:['can','could','will','would'],correct:1,explanation:{correct:'"I wish" + past simple for present unreal situations. "I wish I COULD buy a new car" (but I can\'t).',wrongs:['"Can" is present, not used after "wish"','Opcion correcta','"Will" is future, not used here','"Would" needs a verb after it']}},
  {id:'EN64',area:'ingles',areaName:'Ingles',difficulty:'facil',context:`"Let's go to the ___ to watch a movie."`,question:`Choose the correct place:`,options:['library','cinema','gym','museum'],correct:1,explanation:{correct:'A cinema (or movie theater) is the place to watch a movie.',wrongs:['Libraries have books','Opcion correcta','Gyms are for exercise','Museums have exhibits']}},
  {id:'EN65',area:'ingles',areaName:'Ingles',difficulty:'media',context:`"He is the man ___ helped me yesterday."`,question:`Choose the correct relative pronoun:`,options:['which','who','whose','whom'],correct:1,explanation:{correct:'"Who" is used as a subject pronoun for people. "The man WHO helped me yesterday."',wrongs:['"Which" is for things','Opcion correcta','"Whose" is possessive','"Whom" is object pronoun']}},
  {id:'EN66',area:'ingles',areaName:'Ingles',difficulty:'dificil',context:`"By the time we arrive, they ___ dinner."`,question:`Choose the correct verb form:`,options:['finish','finished','will have finished','are finishing'],correct:2,explanation:{correct:'"By the time" + future reference uses future perfect: "will have finished". Action completed before a future point.',wrongs:['Present simple does not work here','Past simple is for past','Opcion correcta','Present continuous is for ongoing']}},
  {id:'EN67',area:'ingles',areaName:'Ingles',difficulty:'facil',context:`"I'm ___. I want something to eat."`,question:`Choose the correct word:`,options:['thirsty','hungry','tired','sleepy'],correct:1,explanation:{correct:'"Hungry" means wanting or needing food. "I\'m hungry. I want something to eat."',wrongs:['"Thirsty" is for drinks','Opcion correcta','"Tired" is needing rest','"Sleepy" is wanting to sleep']}},
  {id:'EN68',area:'ingles',areaName:'Ingles',difficulty:'media',context:`"It ___ outside now. Take an umbrella."`,question:`Choose the correct verb form:`,options:['rains','rained','is raining','rain'],correct:2,explanation:{correct:'"Now" indicates an action in progress. Present continuous: "It IS RAINING outside now."',wrongs:['"Rains" is present simple for habits','"Rained" is past','Opcion correcta','"Rain" is base form']}},
  {id:'EN69',area:'ingles',areaName:'Ingles',difficulty:'dificil',context:`"She's never been to Europe, ___?"`,question:`Choose the correct tag question:`,options:['has she','is she','hasn\'t she','was she'],correct:0,explanation:{correct:'Negative statement ("never") + positive tag: "has she". The main verb is "has been" so the tag uses "has".',wrongs:['Opcion correcta','"Is" does not match the verb','Negative needs positive tag','"Was" does not match the tense']}},
  {id:'EN70',area:'ingles',areaName:'Ingles',difficulty:'facil',context:`"You ___ brush your teeth before bed."`,question:`Choose the correct modal verb (advice):`,options:['can','should','must','will'],correct:1,explanation:{correct:'"Should" is used for giving advice or recommendations. "You SHOULD brush your teeth before bed."',wrongs:['"Can" expresses ability','Opcion correcta','"Must" is strong obligation','"Will" is future']}},
  {id:'EN71',area:'ingles',areaName:'Ingles',difficulty:'media',context:`"We've been waiting ___ two hours!"`,question:`Choose the correct preposition:`,options:['since','for','during','in'],correct:1,explanation:{correct:'"For" + duration (two hours). "We\'ve been waiting FOR two hours."',wrongs:['"Since" + specific point in time','Opcion correcta','"During" is within a period','"In" is not used with duration like this']}},
  {id:'EN72',area:'ingles',areaName:'Ingles',difficulty:'dificil',context:`"Had I known, I ___ done things differently."`,question:`Choose the correct option:`,options:['will have','would have','have','had'],correct:1,explanation:{correct:'"Had I known" is inverted third conditional (If I had known). Result: "would have done."',wrongs:['Third conditional needs "would have"','Opcion correcta','"Have done" is present perfect','"Had done" is past perfect']}},
  {id:'EN73',area:'ingles',areaName:'Ingles',difficulty:'facil',context:`"This is ___ apple."`,question:`Choose the correct article:`,options:['a','an','the','no article'],correct:1,explanation:{correct:'"Apple" starts with a vowel sound, so use "an": "This is AN apple."',wrongs:['"A" is for consonant sounds','Opcion correcta','"The" would be for a specific apple','An article is needed']}},
  {id:'EN74',area:'ingles',areaName:'Ingles',difficulty:'media',context:`"She speaks French ___ than I do."`,question:`Choose the correct option:`,options:['good','better','best','well'],correct:1,explanation:{correct:'"Than" indicates comparison. Comparative of "well" is "better". "She speaks French BETTER than I do."',wrongs:['"Good" is an adjective','Opcion correcta','"Best" is superlative','"Well" is the positive form']}},
  {id:'EN75',area:'ingles',areaName:'Ingles',difficulty:'dificil',context:`"He suggested that she ___ the doctor."`,question:`Choose the correct verb form:`,options:['see','sees','saw','seeing'],correct:0,explanation:{correct:'After "suggest that" use the subjunctive (base form): "He suggested that she SEE the doctor."',wrongs:['Opcion correcta','Subjunctive uses base form regardless of person','Past is not used after "suggest that"','Gerund is not used after "suggest that"']}},
  {id:'EN76',area:'ingles',areaName:'Ingles',difficulty:'facil',context:`"I have two ___: one brother and one sister."`,question:`Choose the correct word:`,options:['parent','sibling','cousin','nephew'],correct:1,explanation:{correct:'A "sibling" is a brother or sister. "I have two siblings: one brother and one sister."',wrongs:['"Parent" is mother or father','Opcion correcta','"Cousin" is child of an aunt/uncle','"Nephew" is son of a sibling']}},
  {id:'EN77',area:'ingles',areaName:'Ingles',difficulty:'media',context:`"They ___ playing soccer when it started to rain."`,question:`Choose the correct verb form:`,options:['play','are playing','were playing','have played'],correct:2,explanation:{correct:'Past continuous for an action in progress when another action interrupted. "They WERE PLAYING when it started to rain."',wrongs:['"Play" is present','"Are playing" is present','Opcion correcta','"Have played" is present perfect']}},
  {id:'EN78',area:'ingles',areaName:'Ingles',difficulty:'dificil',context:`"I'd rather you ___ the truth."`,question:`Choose the correct verb form:`,options:['tell','told','telling','to tell'],correct:1,explanation:{correct:'"I\'d rather + subject + past simple" for preferences about others. "I\'d rather you TOLD the truth."',wrongs:['"Rather + subject" uses past tense','Opcion correcta','Needs a conjugated verb, not gerund','"Rather" + infinitive is for same subject']}},
  {id:'EN79',area:'ingles',areaName:'Ingles',difficulty:'facil',context:`"February is the ___ month of the year."`,question:`Choose the correct option:`,options:['two','second','twice','double'],correct:1,explanation:{correct:'Ordinal numbers indicate position. "February is the SECOND month of the year."',wrongs:['"Two" is a cardinal number','Opcion correcta','"Twice" means two times','"Double" means twice as much']}},
  {id:'EN80',area:'ingles',areaName:'Ingles',difficulty:'media',context:`"There aren't ___ chairs in the room."`,question:`Choose the correct option:`,options:['some','any','much','a little'],correct:1,explanation:{correct:'"Any" is used in negative sentences with plural countable nouns. "There aren\'t ANY chairs."',wrongs:['"Some" is for affirmative sentences','Opcion correcta','"Much" is for uncountable nouns','"A little" is for uncountable']}},
  {id:'EN81',area:'ingles',areaName:'Ingles',difficulty:'dificil',context:`"It's no use ___ about it now."`,question:`Choose the correct verb form:`,options:['worry','to worry','worrying','worried'],correct:2,explanation:{correct:'"It\'s no use" is followed by the gerund (-ing). "It\'s no use WORRYING about it now."',wrongs:['Base verb is not used after "no use"','Infinitive is not used after "no use"','Opcion correcta','Past participle is not used here']}},
  {id:'EN82',area:'ingles',areaName:'Ingles',difficulty:'facil',context:`"The opposite of 'hot' is ___."`,question:`Choose the correct word:`,options:['warm','cold','cool','wet'],correct:1,explanation:{correct:'The opposite (antonym) of "hot" is "cold".',wrongs:['"Warm" is similar to hot','Opcion correcta','"Cool" is slightly cold','"Wet" is the opposite of dry']}},
  {id:'EN83',area:'ingles',areaName:'Ingles',difficulty:'media',context:`"She ___ be at home. Her car is in the driveway."`,question:`Choose the correct modal verb (deduction):`,options:['can','must','should','would'],correct:1,explanation:{correct:'"Must" is used for logical deduction when evidence suggests something is true. "She MUST be at home."',wrongs:['"Can" expresses general possibility','Opcion correcta','"Should" expresses expectation','"Would" is for hypotheticals']}},
  {id:'EN84',area:'ingles',areaName:'Ingles',difficulty:'dificil',context:`"Seldom ___ such a beautiful sunset."`,question:`Choose the correct option (inversion):`,options:['I have seen','have I seen','I saw','I see'],correct:1,explanation:{correct:'"Seldom" at the beginning requires inversion: "Seldom HAVE I SEEN such a beautiful sunset."',wrongs:['Needs inversion after "seldom"','Opcion correcta','Needs auxiliary verb "have" before subject','Wrong tense and no inversion']}},
  {id:'EN85',area:'ingles',areaName:'Ingles',difficulty:'facil',context:`"The baby is ___ the bed."`,question:`Choose the correct preposition:`,options:['in','on','under','between'],correct:1,explanation:{correct:'"On" is used for surfaces. "The baby is ON the bed." (lying on the surface of the bed).',wrongs:['"In" is for inside something','Opcion correcta','"Under" is beneath','"Between" is in the middle of two things']}},
  {id:'EN86',area:'ingles',areaName:'Ingles',difficulty:'media',context:`"He drives ___ than his brother."`,question:`Choose the correct option:`,options:['more careful','more carefully','carefullier','most carefully'],correct:1,explanation:{correct:'Adverbs with -ly use "more" for the comparative. "He drives MORE CAREFULLY than his brother."',wrongs:['"Careful" is an adjective, not adverb','Opcion correcta','"Carefullier" is not correct English','"Most" is superlative']}},
  {id:'EN87',area:'ingles',areaName:'Ingles',difficulty:'dificil',context:`"Not until later ___ the truth."`,question:`Choose the correct option (inversion):`,options:['she discovered','did she discover','she did discover','discovered she'],correct:1,explanation:{correct:'"Not until" at the beginning requires inversion: "Not until later DID SHE DISCOVER the truth."',wrongs:['Needs inversion with "not until"','Opcion correcta','Incorrect inversion order','Needs auxiliary for inversion']}},
  {id:'EN88',area:'ingles',areaName:'Ingles',difficulty:'facil',context:`"My father's brother is my ___."`,question:`Choose the correct family word:`,options:['grandfather','uncle','cousin','nephew'],correct:1,explanation:{correct:'"My father\'s brother" is "my uncle."',wrongs:['Grandfather is father\'s father','Opcion correcta','Cousin is child of aunt/uncle','Nephew is sibling\'s son']}},
  {id:'EN89',area:'ingles',areaName:'Ingles',difficulty:'media',context:`"Have you ever ___ to London?"`,question:`Choose the correct verb form:`,options:['been','gone','went','go'],correct:0,explanation:{correct:'"Have you ever BEEN to London?" asks about life experience. "Been to" = visited and returned.',wrongs:['Opcion correcta','"Gone to" = currently there','"Went" is past simple, not used with "have"','"Go" is base form']}},
  {id:'EN90',area:'ingles',areaName:'Ingles',difficulty:'dificil',context:`"She insisted that he ___ present at the meeting."`,question:`Choose the correct verb form:`,options:['is','be','was','being'],correct:1,explanation:{correct:'After "insist that" use the subjunctive (base form): "She insisted that he BE present at the meeting."',wrongs:['"Is" is present indicative','Opcion correcta','"Was" is past indicative','"Being" is not correct after "that"']}},
  {id:'EN91',area:'ingles',areaName:'Ingles',difficulty:'facil',context:`"What time do you usually ___ up?"`,question:`Choose the correct verb:`,options:['get','wake','stand','rise'],correct:1,explanation:{correct:'"Wake up" is the phrasal verb meaning to stop sleeping. "What time do you usually WAKE up?"',wrongs:['"Get up" is also possible but the prompt expects a specific verb','Opcion correcta','"Stand up" is to rise from sitting','"Rise" is more formal']}},
  {id:'EN92',area:'ingles',areaName:'Ingles',difficulty:'media',context:`"If I were you, I ___ take that job."`,question:`Choose the correct option:`,options:['will','would','am','do'],correct:1,explanation:{correct:'Second conditional: "If I were you, I WOULD take that job." Giving advice about an unreal situation.',wrongs:['"Will" is for real conditions','Opcion correcta','"Am" is present tense','"Do" is auxiliary, not correct here']}},
  {id:'EN93',area:'ingles',areaName:'Ingles',difficulty:'dificil',context:`"The longer you wait, ___ it becomes."`,question:`Choose the correct option:`,options:['the hardest','the harder','harder','more hard'],correct:1,explanation:{correct:'"The + comparative, the + comparative" structure: "The longer you wait, THE HARDER it becomes."',wrongs:['"Hardest" is superlative, not used here','Opcion correcta','Needs "the" before "harder"','"More hard" is not correct form']}},
  {id:'EN94',area:'ingles',areaName:'Ingles',difficulty:'facil',context:`"I need to buy some food. Let's go to the ___."`,question:`Choose the correct place:`,options:['bank','supermarket','library','post office'],correct:1,explanation:{correct:'A "supermarket" is where you buy food and household items.',wrongs:['Banks are for money','Opcion correcta','Libraries have books','Post offices send mail']}},
  {id:'EN95',area:'ingles',areaName:'Ingles',difficulty:'media',context:`"The exam was ___ difficult that nobody finished."`,question:`Choose the correct option:`,options:['so','such','too','very'],correct:0,explanation:{correct:'"So + adjective + that" expresses cause and effect. "The exam was SO difficult that nobody finished."',wrongs:['Opcion correcta','"Such" is used with nouns (such a difficult exam)','"Too" needs "to" (too difficult to finish)','"Very" does not work with "that"']}},
  {id:'EN96',area:'ingles',areaName:'Ingles',difficulty:'dificil',context:`"She ought ___ apologized for her behavior."`,question:`Choose the correct option:`,options:['have','to have','had','having'],correct:1,explanation:{correct:'"Ought to have + past participle" expresses regret or criticism about the past. "She ought TO HAVE apologized."',wrongs:['"Ought have" is missing "to"','Opcion correcta','"Ought had" is not grammatical','"Ought having" is not correct']}},
  {id:'EN97',area:'ingles',areaName:'Ingles',difficulty:'facil',context:`"Please ___ quiet. The baby is sleeping."`,options:['be','being','to be','been'],correct:0,explanation:{correct:'Imperative: "Please BE quiet." Use the base form of the verb for commands/requests.',wrongs:['Opcion correcta','"Being" is not used for imperatives','"To be" is infinitive, not imperative','"Been" is past participle']}},
  {id:'EN98',area:'ingles',areaName:'Ingles',difficulty:'media',context:`"We're looking forward ___ you next week."`,question:`Choose the correct preposition:`,options:['for','to','at','on'],correct:1,explanation:{correct:'"Look forward to + gerund/noun." "We\'re looking forward TO seeing you next week."',wrongs:['"For" is not used with "look forward"','Opcion correcta','"At" is not correct here','"On" is not correct here']}},
  {id:'EN99',area:'ingles',areaName:'Ingles',difficulty:'dificil',context:`"He ran out of the room ___ he heard the news."`,question:`Choose the correct conjunction:`,options:['as soon as','as long as','in case','unless'],correct:0,explanation:{correct:'"As soon as" means immediately after. "He ran out of the room AS SOON AS he heard the news."',wrongs:['Opcion correcta','"As long as" = provided that','"In case" = as a precaution','"Unless" = if not']}},
  {id:'EN100',area:'ingles',areaName:'Ingles',difficulty:'facil',context:`"There are twelve months in a ___."`,question:`Choose the correct word:`,options:['week','year','day','hour'],correct:1,explanation:{correct:'"There are twelve months in a YEAR." A year has 12 months.',wrongs:['A week has 7 days','Opcion correcta','A day has 24 hours','An hour has 60 minutes']}}
);
